/* DAWAH X — ahmad, অধ্যায় 104 · খণ্ড 104 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][104]=[[20601,20601,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي بَيْعِ ‏ ‏الْعَرَايَا ‏ ‏بِخَرْصِهَا ‏","","",""],[20602,20602,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الثَّمَرِ بِالتَّمْرِ فَأَخْبَرَهُمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي ‏ ‏الْعَرَايَا ‏","","",""],[20603,20603,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْنَا إِلَى الْمَسْجِدِ فَأُقِيمَتْ الصَّلَاةُ قُلْتُ كَمْ كَانَ بَيْنَهُمَا قَالَ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ ‏ ‏آيَةً ‏","","",""],[20604,20604,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الْعُمْرَى ‏ ‏لِلْوَارِثِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً قَضَى ‏ ‏بِالْعُمْرَى ‏","","",""],[20605,20605,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُحْسِنُ ‏ ‏السُّرْيَانِيَّةَ ‏ ‏إِنَّهَا تَأْتِينِي كُتُبٌ قَالَ قُلْتُ لَا قَالَ فَتَعَلَّمْهَا فَتَعَلَّمْتُهَا فِي سَبْعَةَ عَشَرَ يَوْمًا ‏","","",""],[20606,20606,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏يَغْفِرُ اللَّهُ ‏ ‏لِرَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَا وَاللَّهِ أَعْلَمُ بِالْحَدِيثِ مِنْهُ إِنَّمَا ‏ ‏أَتَى رَجُلَانِ قَدْ اقْتَتَلَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ هَذَا شَأْنَكُمْ فَلَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ قَالَ فَسَمِعَ ‏ ‏رَافِعٌ ‏ ‏قَوْلَهُ لَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ ‏","","",""],[20607,20607,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سِنَانٍ سَعِيدُ بْنُ سِنَانٍ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏أُبَيَّ بْنَ كَعْبٍ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا الْمُنْذِرِ ‏ ‏إِنَّهُ قَدْ وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ هَذَا الْقَدَرِ فَحَدِّثْنِي بِشَيْءٍ لَعَلَّهُ يَذْهَبُ مِنْ قَلْبِي قَالَ ‏ ‏لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ كَانَتْ رَحْمَتُهُ لَهُمْ خَيْرًا مِنْ أَعْمَالِهِمْ وَلَوْ أَنْفَقْتَ جَبَلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا فِي ‏ ‏سَبِيلِ اللَّهِ عَزَّ وَجَلَّ مَا قَبِلَهُ اللَّهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ وَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ وَلَوْ مِتَّ عَلَى غَيْرِ ذَلِكَ لَدَخَلْتَ النَّارَ ‏ ‏قَالَ ‏ ‏فَأَتَيْتُ ‏ ‏حُذَيْفَةَ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏مِثْلَ ذَلِكَ ‏ ‏وَأَتَيْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏مِثْلَ ذَلِكَ ‏ ‏وَأَتَيْتُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَحَدَّثَنِي ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[20608,20608,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سُلَيْمَانَ ‏ ‏مِنْ وَلَدِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏خَرَجَ مِنْ عِنْدِ ‏ ‏مَرْوَانَ ‏ ‏نَحْوًا مِنْ نِصْفِ النَّهَارِ فَقُلْنَا مَا بَعَثَ إِلَيْهِ السَّاعَةَ إِلَّا لِشَيْءٍ سَأَلَهُ عَنْهُ فَقُمْتُ إِلَيْهِ فَسَأَلْتُهُ فَقَالَ أَجَلْ سَأَلَنَا عَنْ أَشْيَاءَ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نَضَّرَ ‏ ‏اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَحَفِظَهُ حَتَّى يُبَلِّغَهُ غَيْرَهُ فَإِنَّهُ رُبَّ حَامِلِ فِقْهٍ لَيْسَ بِفَقِيهٍ وَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ ثَلَاثُ خِصَالٍ لَا ‏ ‏يَغِلُّ ‏ ‏عَلَيْهِنَّ قَلْبُ مُسْلِمٍ أَبَدًا إِخْلَاصُ الْعَمَلِ لِلَّهِ وَمُنَاصَحَةُ ‏ ‏وُلَاةِ ‏ ‏الْأَمْرِ وَلُزُومُ الْجَمَاعَةِ فَإِنَّ دَعْوَتَهُمْ تُحِيطُ مِنْ وَرَائِهِمْ وَقَالَ مَنْ كَانَ هَمُّهُ الْآخِرَةَ جَمَعَ اللَّهُ شَمْلَهُ وَجَعَلَ غِنَاهُ فِي قَلْبِهِ وَأَتَتْهُ الدُّنْيَا وَهِيَ ‏ ‏رَاغِمَةٌ ‏ ‏وَمَنْ كَانَتْ ‏ ‏نِيَّتُهُ ‏ ‏الدُّنْيَا فَرَّقَ اللَّهُ عَلَيْهِ ضَيْعَتَهُ وَجَعَلَ فَقْرَهُ بَيْنَ عَيْنَيْهِ وَلَمْ يَأْتِهِ مِنْ الدُّنْيَا إِلَّا مَا كُتِبَ لَهُ وَسَأَلَنَا عَنْ الصَّلَاةِ الْوُسْطَى وَهِيَ الظُّهْرُ ‏","","",""],[20609,20609,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّجْمَ ‏ ‏فَلَمْ يَسْجُدْ ‏","","",""],[20610,20610,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي الْجَهْمِ بْنِ صُخَيْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْخَوْفِ ‏ ‏بِذِي قَرَدٍ ‏ ‏أَرْضٌ مِنْ أَرْضِ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏فَصَفَّ النَّاسُ خَلْفَهُ صَفَّيْنِ صَفًّا ‏ ‏يُوَازِي الْعَدُوَّ وَصَفًّا خَلْفَهُ فَصَلَّى بِالصَّفِّ الَّذِي يَلِيهِ رَكْعَةً ثُمَّ ‏ ‏نَكَصَ ‏ ‏هَؤُلَاءِ إِلَى ‏ ‏مَصَافِّ ‏ ‏هَؤُلَاءِ وَهَؤُلَاءِ إِلَى ‏ ‏مَصَافِّ ‏ ‏هَؤُلَاءِ فَصَلَّى بِهِمْ رَكْعَةً أُخْرَى ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ الْفَزَارِيِّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةَ الْخَوْفِ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ عَبَّاسٍ ‏","","",""],[20611,20611,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بِسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ بِحُجْرَةٍ فَكَانَ ‏ ‏يَخْرُجُ ‏ ‏يُصَلِّي فِيهَا ‏ ‏فَفَطِنَ ‏ ‏لَهُ أَصْحَابُهُ فَكَانُوا يُصَلُّونَ بِصَلَاتِهِ ‏","","",""],[20612,20612,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ أَبِي حَكِيمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الزِّبْرِقَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الظُّهْرَ ‏ ‏بِالْهَاجِرَةِ ‏ ‏وَلَمْ يَكُنْ ‏ ‏يُصَلِّي صَلَاةً أَشَدَّ عَلَى ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا قَالَ فَنَزَلَتْ ‏ { ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى ‏} ‏وَقَالَ إِنَّ قَبْلَهَا صَلَاتَيْنِ وَبَعْدَهَا صَلَاتَيْنِ ‏","","",""],[20613,20613,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ الصَّلْتِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ الْعَاصِ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏يَكْتُبَانِ الْمَصَاحِفَ فَمَرُّوا عَلَى هَذِهِ الْآيَةِ فَقَالَ ‏ ‏زَيْدٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الشَّيْخُ وَالشَّيْخَةُ إِذَا زَنَيَا فَارْجُمُوهُمَا ‏ ‏الْبَتَّةَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَمَّا أُنْزِلَتْ هَذِهِ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أَكْتِبْنِيهَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَكَأَنَّهُ كَرِهَ ذَلِكَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَلَا ‏ ‏تَرَى أَنَّ الشَّيْخَ إِذَا لَمْ ‏ ‏يُحْصَنْ ‏ ‏جُلِدَ وَأَنَّ الشَّابَّ إِذَا زَنَى وَقَدْ ‏ ‏أُحْصِنَ ‏ ‏رُجِمَ ‏","","",""],[20614,20614,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَاضِرَ بْنَ الْمُهَاجِرِ الْبَاهِلِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ ذِئْبًا ‏ ‏نَيَّبَ ‏ ‏فِي شَاةٍ فَذَبَحُوهَا بِمَرْوَةٍ فَرَخَّصَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَكْلِهَا ‏","","",""],[20615,20615,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20616,20616,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى ‏ ‏أُحُدٍ ‏ ‏فَرَجَعَ أُنَاسٌ خَرَجُوا مَعَهُ فَكَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرْقَتَيْنِ فِرْقَةٌ تَقُولُ بِقِتْلَتِهِمْ وَفِرْقَةٌ تَقُولُ لَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي ‏ ‏الْخَبَثَ ‏ ‏كَمَا تَنْفِي النَّارُ ‏ ‏خَبَثَ ‏ ‏الْفِضَّةِ ‏","","",""],[20617,20617,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أُمِرْنَا أَنْ نُسَبِّحَ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ وَنَحْمَدَ ثَلَاثًا وَثَلَاثِينَ وَنُكَبِّرَ أَرْبَعًا وَثَلَاثِينَ فَأُتِيَ رَجُلٌ فِي الْمَنَامِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقِيلَ لَهُ أَمَرَكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُسَبِّحُوا فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ كَذَا وَكَذَا قَالَ الْأَنْصَارِيُّ فِي مَنَامِهِ نَعَمْ قَالَ فَاجْعَلُوهَا خَمْسًا وَعِشْرِينَ خَمْسًا وَعِشْرِينَ وَاجْعَلُوا فِيهَا ‏ ‏التَّهْلِيلَ ‏ ‏فَلَمَّا أَصْبَحَ ‏ ‏غَدَا ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَافْعَلُوا ‏","","",""],[20618,20618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ ذُؤَيْبٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَكْتُبُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اكْتُبْ لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ فَجَاءَ ‏ ‏عَبْدُ اللَّهِ ابْنُ أُمِّ مَكْتُومٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أُحِبُّ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَلَكِنْ بِي مِنْ ‏ ‏الزَّمَانَةِ ‏ ‏وَقَدْ ‏ ‏تَرَى وَذَهَبَ بَصَرِي قَالَ ‏ ‏زَيْدٌ ‏ ‏فَثَقُلَتْ فَخِذُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فَخِذِي حَتَّى خَشِيتُ أَنْ ‏ ‏تَرُضَّهَا ‏ ‏فَقَالَ اكْتُبْ ‏ { ‏لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ غَيْرُ ‏ ‏أُولِي ‏ ‏الضَّرَرِ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ ‏} ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏سَهْلُ بْنُ سَعْدٍ السَّاعِدِيُّ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ ‏ ‏مَرْوَانَ بْنَ الْحَكَمِ ‏ ‏جَالِسًا فِي الْمَسْجِدِ فَأَقْبَلْتُ حَتَّى جَلَسْتُ إِلَى جَنْبِهِ ‏ ‏فَأَخْبَرَنَا أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْلَى عَلَيْهِ ‏ { ‏لَا يَسْتَوِي الْقَاعِدُونَ ‏} ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[20619,20619,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً فَسَمِعَ أَهْلُ الْمَسْجِدِ صَلَاتَهُ قَالَ فَكَثُرَ النَّاسُ اللَّيْلَةَ الثَّانِيَةَ فَخَفِيَ عَلَيْهِمْ صَوْتُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلُوا ‏ ‏يَسْتَأْنِسُونَ ‏ ‏وَيَتَنَحْنَحُونَ ‏ ‏قَالَ فَاطَّلَعَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا زِلْتُمْ بِالَّذِي تَصْنَعُونَ حَتَّى خَشِيتُ أَنْ يُكْتَبَ عَلَيْكُمْ وَلَوْ كُتِبَتْ عَلَيْكُمْ مَا قُمْتُمْ بِهَا وَإِنَّ أَفْضَلَ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا صَلَاةَ الْمَكْتُوبَةِ ‏","","",""],[20620,20620,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ قَالَ قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏","","",""],[20621,20621,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِمَاسَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا حِينَ قَالَ ‏ ‏طُوبَى ‏ ‏لِلشَّامِ ‏ ‏طُوبَى ‏ ‏لِلشَّامِ ‏ ‏قُلْتُ مَا بَالُ ‏ ‏الشَّامِ ‏ ‏قَالَ ‏ ‏الْمَلَائِكَةُ بَاسِطُو أَجْنِحَتِهَا عَلَى ‏ ‏الشَّامِ ‏","","",""],[20622,20622,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ شِمَاسَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُؤَلِّفُ الْقُرْآنَ مِنْ ‏ ‏الرِّقَاعِ ‏ ‏إِذْ قَالَ ‏ ‏طُوبَى ‏ ‏لِلشَّامِ ‏ ‏قِيلَ وَلِمَ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِنَّ مَلَائِكَةَ الرَّحْمَنِ بَاسِطَةٌ أَجْنِحَتَهَا عَلَيْهَا ‏","","",""],[20623,20623,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏يُخْبِرُنِي عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏فِي الْمَسْجِدِ ‏ ‏قُلْتُ ‏ ‏لِابْنِ لَهِيعَةَ ‏ ‏فِي مَسْجِدِ بَيْتِهِ ‏ ‏قَالَ ‏ ‏لَا فِي ‏ ‏مَسْجِدِ الرَّسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[20624,20624,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏أَوْ ‏ ‏أَبَا أَيُّوبَ ‏ ‏قَالَ ‏ ‏لِمَرْوَانَ ‏ ‏أَلَمْ ‏ ‏أَرَكَ قَصَّرْتَ سَجْدَتَيْ الْمَغْرِبِ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِيهَا ‏ ‏بِالْأَعْرَافِ ‏","","",""],[20625,20625,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اطَّلَعَ قِبَلَ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ أَقْبِلْ بِقُلُوبِهِمْ وَاطَّلَعَ مِنْ قِبَلِ كَذَا فَقَالَ اللَّهُمَّ أَقْبِلْ بِقُلُوبِهِمْ وَبَارِكْ لَنَا فِي ‏ ‏صَاعِنَا ‏ ‏وَمُدِّنَا ‏","","",""],[20626,20626,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سِنَانٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏وَهْبِ بْنِ خَالِدٍ الْحِمْصِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ الْقَدَرِ فَأَتَيْتُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَسَأَلْتُهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَاوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ غَيْرَ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ كَانَتْ رَحْمَتُهُ لَهُمْ خَيْرًا مِنْ أَعْمَالِهِمْ وَلَوْ كَانَ لَكَ جَبَلُ ‏ ‏أُحُدٍ ‏ ‏أَوْ مِثْلُ جَبَلِ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا أَنْفَقْتَهُ فِي سَبِيلِ اللَّهِ مَا قَبِلَهُ اللَّهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ وَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَأَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ وَأَنَّكَ إِنْ مِتَّ عَلَى غَيْرِ هَذَا دَخَلْتَ النَّارَ ‏","","",""],[20627,20627,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَبِيصَةَ بْنَ ذُؤَيْبٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْ آلَ ‏ ‏الزُّبَيْرِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عِنْدَهَا رَكْعَتَيْنِ بَعْدَ الْعَصْرِ فَكَانُوا يُصَلُّونَهَا ‏ ‏قَالَ ‏ ‏قَبِيصَةُ ‏ ‏فَقَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏يَغْفِرُ اللَّهُ ‏ ‏لِعَائِشَةَ ‏ ‏نَحْنُ أَعْلَمُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَائِشَةَ ‏ ‏إِنَّمَا كَانَ ذَلِكَ لِأَنَّ أُنَاسًا مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَجِيرٍ ‏ ‏فَقَعَدُوا يَسْأَلُونَهُ ‏ ‏وَيُفْتِيهِمْ حَتَّى صَلَّى الظُّهْرَ وَلَمْ يُصَلِّ رَكْعَتَيْنِ ثُمَّ قَعَدَ ‏ ‏يُفْتِيهِمْ حَتَّى صَلَّى الْعَصْرَ فَانْصَرَفَ إِلَى بَيْتِهِ فَذَكَرَ أَنَّهُ لَمْ يُصَلِّ بَعْدَ الظُّهْرِ شَيْئًا فَصَلَّاهُمَا بَعْدَ الْعَصْرِ يَغْفِرُ اللَّهُ ‏ ‏لِعَائِشَةَ ‏ ‏نَحْنُ أَعْلَمُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَائِشَةَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ ذُؤَيْبٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْ آلَ ‏ ‏الزُّبَيْرِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[20628,20628,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏","","",""],[20629,20629,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبِيعُوا الثَّمَرَةَ حَتَّى يَبْدُوَ صَلَاحُهَا ‏","","",""],[20630,20630,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏تَسَحَّرَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ خَرَجْنَا إِلَى الصَّلَاةِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِزَيْدٍ ‏ ‏كَمْ بَيْنَ ذَلِكَ ‏ ‏قَالَ ‏ ‏قَدْرُ قِرَاءَةِ خَمْسِينَ آيَةً ‏","","",""],[20631,20631,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ خُطَبَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَعَلَ مِنْهُمْ مَنْ يَقُولُ ‏ ‏يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا اسْتَعْمَلَ رَجُلًا مِنْكُمْ قَرَنَ مَعَهُ رَجُلًا مِنَّا ‏ ‏فَنَرَى أَنْ يَلِيَ هَذَا الْأَمْرَ رَجُلَانِ أَحَدُهُمَا مِنْكُمْ وَالْآخَرُ مِنَّا قَالَ فَتَتَابَعَتْ خُطَبَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏عَلَى ذَلِكَ قَالَ فَقَامَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏فَقَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَإِنَّمَا الْإِمَامُ يَكُونُ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَنَحْنُ أَنْصَارُهُ كَمَا كُنَّا أَنْصَارَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ ‏ ‏جَزَاكُمْ اللَّهُ خَيْرًا مِنْ حَيٍّ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏وَثَبَّتَ قَائِلَكُمْ ثُمَّ قَالَ وَاللَّهِ لَوْ فَعَلْتُمْ غَيْرَ ذَلِكَ لَمَا صَالَحْنَاكُمْ ‏","","",""],[20632,20632,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏زَيْدًا ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏لَمَّا قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏ذُهِبَ بِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُعْجِبَ بِي فَقَالُوا يَا رَسُولَ اللَّهِ هَذَا غُلَامٌ مِنْ ‏ ‏بَنِي النَّجَّارِ ‏ ‏مَعَهُ مِمَّا أَنْزَلَ اللَّهُ عَلَيْكَ بِضْعَ عَشْرَةَ سُورَةً فَأَعْجَبَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ يَا ‏ ‏زَيْدُ ‏ ‏تَعَلَّمْ لِي كِتَابَ ‏ ‏يَهُودَ ‏ ‏فَإِنِّي وَاللَّهِ مَا آمَنُ ‏ ‏يَهُودَ ‏ ‏عَلَى كِتَابِي قَالَ ‏ ‏زَيْدٌ ‏ ‏فَتَعَلَّمْتُ كِتَابَهُمْ مَا مَرَّتْ بِي خَمْسَ عَشْرَةَ لَيْلَةً حَتَّى ‏ ‏حَذَقْتُهُ ‏ ‏وَكُنْتُ أَقْرَأُ لَهُ كُتُبَهُمْ إِذَا كَتَبُوا إِلَيْهِ وَأُجِيبُ عَنْهُ إِذَا كَتَبَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْدَمَهُ ‏ ‏الْمَدِينَةَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[20633,20633,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏ح ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏ح ‏ ‏وَوَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجْنَا إِلَى الْمَسْجِدِ وَأُقِيمَتْ الصَّلَاةُ ‏ ‏فَقُلْتُ كَمْ بَيْنَهُمَا قَالَ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً قَالَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي حَدِيثِهِ فَقُلْتُ ‏ ‏لِزَيْدٍ ‏ ‏كَمْ كَانَ قَدْرُ مَا بَيْنَهُمَا قَالَ نَحْوًا مِنْ خَمْسِينَ آيَةً ‏","","",""],[20634,20634,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْنَا إِلَى الْمَسْجِدِ فَأُقِيمَتْ الصَّلَاةُ ‏ ‏قُلْتُ كَمْ كَانَ بَيْنَهُمَا قَالَ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً ‏","","",""],[20635,20635,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ الْقِرَاءَةِ فِي الظُّهْرِ وَالْعَصْرِ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطِيلُ الْقِيَامَ وَيُحَرِّكُ شَفَتَيْهِ ‏","","",""],[20636,20636,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّجْمِ ‏ ‏فَلَمْ يَسْجُدْ فِيهَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏قَرَأْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[20637,20637,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا الْمَكْتُوبَةَ ‏","","",""],[20638,20638,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَعُثْمَانُ بْنُ عُمَرَ ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَقَالَ ‏ ‏عُثْمَانُ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[20639,20639,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏أَمْلَاهُ عَلَيْنَا ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الرُّقْبَى ‏ ‏لِلْوَارِثِ ‏","","",""],[20640,20640,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ لِصَاحِبِ ‏ ‏الْعَرِيَّةِ ‏ ‏أَنْ يَبِيعَهَا ‏ ‏بِخَرْصِهَا ‏","","",""],[20641,20641,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏يَغْفِرُ اللَّهُ ‏ ‏لِرَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَا وَاللَّهِ أَعْلَمُ بِالْحَدِيثِ مِنْهُ إِنَّمَا ‏ ‏أَتَى رَجُلَانِ قَدْ اقْتَتَلَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ هَذَا شَأْنَكُمْ فَلَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ ‏ ‏قَالَ ‏ ‏فَسَمِعَ ‏ ‏رَافِعٌ ‏ ‏قَوْلَهُ لَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ ‏","","",""],[20642,20642,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏} ‏قَالَ قَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى خَتَمَهَا وَقَالَ النَّاسُ ‏ ‏حَيِّزٌ ‏ ‏وَأَنَا وَأَصْحَابِي ‏ ‏حَيِّزٌ ‏ ‏وَقَالَ لَا هِجْرَةَ بَعْدَ الْفَتْحِ وَلَكِنْ جِهَادٌ وَنِيَّةٌ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مَرْوَانُ ‏ ‏كَذَبْتَ وَعِنْدَهُ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏وَهُمَا قَاعِدَانِ مَعَهُ عَلَى السَّرِيرِ فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏لَوْ شَاءَ هَذَانِ لَحَدَّثَاكَ فَرَفَعَ عَلَيْهِ ‏ ‏مَرْوَانُ ‏ ‏الدِّرَّةَ ‏ ‏لِيَضْرِبَهُ فَلَمَّا رَأَيَا ذَلِكَ قَالَا ‏ ‏صَدَقَ ‏","","",""],[20643,20643,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى ‏ ‏أُحُدٍ ‏ ‏فَرَجَعَ أُنَاسٌ خَرَجُوا مَعَهُ فَكَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ فِرْقَتَيْنِ فِرْقَةٌ تَقُولُ بِقَتْلِهِمْ وَفِرْقَةٌ تَقُولُ لَا ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَكَانَ النَّاسُ فِيهِمْ فِرْقَتَيْنِ فَرِيقًا يَقُولُونَ بِقَتْلِهِمْ وَفَرِيقًا يَقُولُونَ لَا ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏ ‏حَدَّثَنَاه ‏ ‏عَفَّانُ ‏ ‏وَقَالَ ‏ ‏فِيهِ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏بَهْزٍ ‏","","",""],[20644,20644,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الْحَجَّاجِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُخَابَرَةِ ‏ ‏قُلْتُ وَمَا ‏ ‏الْمُخَابَرَةُ ‏ ‏قَالَ يَأْجُرُ الْأَرْضَ بِنِصْفٍ أَوْ بِثُلُثٍ أَوْ بِرُبُعٍ ‏","","",""],[20645,20645,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏احْتَجَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ حُجْرَةً وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ مِنْ اللَّيْلِ فَيُصَلِّي فِيهَا فَصَلَّوْا مَعَهُ بِصَلَاتِهِ ‏ ‏يَعْنِي رِجَالًا ‏ ‏وَكَانُوا يَأْتُونَهُ كُلَّ لَيْلَةٍ حَتَّى إِذَا كَانَ لَيْلَةٌ مِنْ اللَّيَالِي لَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَنَحْنَحُوا وَرَفَعُوا أَصْوَاتَهُمْ قَالَ فَخَرَجَ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُغْضَبًا قَالَ فَقَالَ لَهُمْ أَيُّهَا النَّاسُ ‏ ‏مَا زَالَ بِكُمْ صَنِيعُكُمْ حَتَّى ظَنَنْتُ أَنْ سَيُكْتَبُ عَلَيْكُمْ فَعَلَيْكُمْ بِالصَّلَاةِ فِي بُيُوتِكُمْ فَإِنَّ خَيْرَ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا الصَّلَاةَ الْمَكْتُوبَةَ ‏","","",""],[20646,20646,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَلَمْ أَرَكَ اللَّيْلَةَ ‏ ‏خَفَّفْتَ الْقِرَاءَةَ فِي سَجْدَتَيْ الْمَغْرِبِ وَالَّذِي نَفْسِي بِيَدِهِ إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَقْرَأُ فِيهِمَا ‏ ‏بِطُولَى ‏ ‏الطُّولَيَيْنِ ‏","","",""],[20647,20647,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أُحُدٍ ‏ ‏رَجَعَ أُنَاسٌ خَرَجُوا مَعَهُ فَكَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرْقَتَيْنِ فِرْقَةٌ تَقُولُ نَقْتُلُهُمْ وَفِرْقَةٌ تَقُولُ لَا ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَكَانَ فَرِيقٌ يَقُولُونَ قَتْلَهُمْ وَفَرِيقٌ يَقُولُونَ لَا ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَأَنْزَلَ اللَّهُ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏","","",""],[20648,20648,"","","‏ ‏حَدَّثَنَا ‏ ‏فَيَّاضُ بْنُ مُحَمَّدٍ أَبُو مُحَمَّدٍ الرَّقِّيُّ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ يَعْنِي ابْنَ بُرْقَانَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الْحَجَّاجِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُخَابَرَةِ ‏ ‏قَالَ وَقِيلَ لَهُ مَا ‏ ‏الْمُخَابَرَةُ ‏ ‏قَالَ أَنْ تَأْخُذَ الْأَرْضَ بِنِصْفٍ أَوْ بِثُلُثٍ أَوْ بِرُبُعٍ أَوْ بِأَشْبَاهِ هَذَا ‏","","",""],[20649,20649,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ فِي هَذِهِ الْآيَةِ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ وَاللَّهُ ‏ ‏أَرْكَسَهُمْ ‏ ‏بِمَا كَسَبُوا ‏} ‏قَالَ رَجَعَ أُنَاسٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ النَّاسُ فِيهِمْ فِرْقَتَيْنِ فَرِيقٌ يَقُولُونَ قَتْلَهُمْ وَفَرِيقٌ يَقُولُونَ لَا فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏وَقَالَ إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏","","",""],[20650,20650,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ أَبُو الْأَسْوَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏تَسَحَّرَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ خَرَجْنَا حَتَّى أَتَيْنَا الصَّلَاةَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَقُلْتُ ‏ ‏لِزَيْدٍ ‏ ‏كَمْ كَانَ بَيْنَ ذَلِكَ ‏ ‏قَالَ ‏ ‏قَدْرُ قِرَاءَةِ خَمْسِينَ آيَةً ‏ ‏أَوْ سِتِّينَ آيَةً ‏","","",""],[20651,20651,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي بَيْعِ ‏ ‏الْعَرَايَا ‏ ‏بِخَرْصِهَا ‏ ‏كَيْلًا ‏","","",""],[20652,20652,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏وَعَطِيَّةَ ‏ ‏وَضَمْرَةَ ‏ ‏وَرَاشِدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏سُئِلَ عَنْ زَوْجٍ وَأُخْتٍ لِأُمٍّ وَأَبٍ فَأَعْطَى الزَّوْجَ النِّصْفَ وَالْأُخْتَ النِّصْفَ فَكُلِّمَ فِي ذَلِكَ فَقَالَ حَضَرْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِذَلِكَ ‏","","",""],[20653,20653,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏خَارِجَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَسَخْنَا الْمَصَاحِفَ ‏ ‏فُقِدَتْ آيَةٌ مِنْ سُورَةِ ‏ ‏الْأَحْزَابِ ‏ ‏قَدْ كُنْتُ أَسْمَعُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا فَالْتَمَسْتُهَا فَلَمْ أَجِدْهَا مَعَ أَحَدٍ إِلَّا مَعَ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏الَّذِي جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهَادَتَهُ شَهَادَةَ رَجُلَيْنِ قَوْلُ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏مِنْ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ‏}","","",""],[20654,20654,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ لَهُ مَا لِي أَرَاكَ ‏ ‏تَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ السُّوَرِ قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِيهَا ‏ ‏بِطُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏وَمَا ‏ ‏طُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏الْأَعْرَافُ ‏","","",""],[20655,20655,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏خَارِجَةَ بْنَ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20656,20656,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏خَارِجَةُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏يَقُولُ ‏ ‏فُقِدَتْ آيَةٌ مِنْ سُورَةِ ‏ ‏الْأَحْزَابِ ‏ ‏حِينَ نَسَخْنَا الْمَصَاحِفَ قَدْ كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا ‏ { ‏رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ‏} ‏فَالْتَمَسْتُهَا فَوَجَدْتُهَا مَعَ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏فَأَلْحَقْتُهَا فِي سُورَتِهَا فِي الْمُصْحَفِ ‏","","",""],[20657,20657,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَ إِلَيَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَقْتَلَ أَهْلِ ‏ ‏الْيَمَامَةِ ‏ ‏فَإِذَا ‏ ‏عُمَرُ ‏ ‏عِنْدَهُ جَالِسٌ وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا ‏ ‏زَيْدُ بْنَ ثَابِتٍ ‏ ‏إِنَّكَ غُلَامٌ شَابٌّ عَاقِلٌ لَا نَتَّهِمُكَ قَدْ كُنْتَ تَكْتُبُ الْوَحْيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَتَبَّعْ الْقُرْآنَ فَاجْمَعْهُ قَالَ ‏ ‏زَيْدٌ ‏ ‏فَوَاللَّهِ ‏ ‏لَوْ كَلَّفُونِي نَقْلَ جَبَلٍ مِنْ الْجِبَالِ مَا كَانَ أَثْقَلَ عَلَيَّ مِمَّا أَمَرَنِي بِهِ مِنْ جَمْعِ الْقُرْآنِ فَقُلْتُ أَتَفْعَلَانِ شَيْئًا لَمْ يَفْعَلْهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هُوَ وَاللَّهِ خَيْرٌ فَلَمْ يَزَلْ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُرَاجِعُنِي حَتَّى شَرَحَ اللَّهُ صَدْرِي بِالَّذِي شَرَحَ لَهُ صَدْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏","","",""],[20658,20658,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الرُّقْبَى ‏ ‏لِلَّذِي ‏ ‏أُرْقِبَهَا ‏ ‏وَالْعُمْرَى ‏ ‏لِلَّذِي ‏ ‏أُعْمِرَهَا ‏","","",""],[20659,20659,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي مُلَيْكَةَ ‏ ‏يُحَدِّثُ يَقُولُ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏قَالَ لِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏مَا لَكَ ‏ ‏تَقْرَأُ فِي الْمَغْرِبِ ‏ ‏بِقِصَارِ ‏ ‏الْمُفَصَّلِ ‏ ‏لَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الْمَغْرِبِ ‏ ‏طُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعُرْوَةَ ‏ ‏مَا ‏ ‏طُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏الْأَعْرَافُ ‏","","",""],[20660,20660,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ فِي كِتَابِ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْوُضُوءِ مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20661,20661,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعُمْرَى ‏ ‏لِلْوَارِثِ ‏","","",""],[20662,20662,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏طَاوُسًا ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حُجْرًا الْمَدَرِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعُمْرَى ‏ ‏فِي الْمِيرَاثِ ‏","","",""],[20663,20663,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُرْقِبُوا ‏ ‏فَمَنْ ‏ ‏أَرْقَبَ ‏ ‏فَسَبِيلُ الْمِيرَاثِ ‏","","",""],[20664,20664,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏شِبْلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏أَعْمَرَ ‏ ‏عُمْرَى ‏ ‏فَهِيَ لِمُعْمِرِهِ مَحْيَاهُ وَمَمَاتَهُ لَا ‏ ‏تُرْقِبُوا ‏ ‏فَمَنْ ‏ ‏أَرْقَبَ ‏ ‏شَيْئًا فَهُوَ سَبِيلُ الْمِيرَاثِ ‏","","",""],[20665,20665,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏أَوْ غَيْرِهِ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏لَمَّا كُتِبَتْ الْمَصَاحِفُ فَقَدْتُ آيَةً كُنْتُ أَسْمَعُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُهَا عِنْدَ ‏ ‏خُزَيْمَةَ الْأَنْصَارِيِّ ‏ { ‏مِنْ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ‏ ‏إِلَى ‏ ‏تَبْدِيلًا ‏} ‏قَالَ فَكَانَ ‏ ‏خُزَيْمَةُ ‏ ‏يُدْعَى ذَا الشَّهَادَتَيْنِ ‏ ‏أَجَازَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهَادَتَهُ بِشَهَادَةِ رَجُلَيْنِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَقُتِلَ يَوْمَ ‏ ‏صِفِّينَ ‏ ‏مَعَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏","","",""],[20666,20666,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏وَهْبٍ الْحِمْصِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏أُبَيَّ بْنَ كَعْبٍ ‏ ‏فَقُلْتُ لَهُ إِنَّهُ قَدْ وَقَعَ فِي نَفْسِي مِنْ الْقَدَرِ شَيْءٌ فَأُحِبُّ أَنْ تُحَدِّثَنِي بِحَدِيثٍ لَعَلَّ اللَّهَ أَنْ يُذْهِبَ عَنِّي مَا أَجِدُ قَالَ ‏ ‏لَوْ أَنَّ اللَّهَ عَزَّ وَجَلَّ عَذَّبَ أَهْلَ السَّمَوَاتِ وَأَهْلَ الْأَرْضِ عَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ كَانَتْ رَحْمَتُهُ لَهُمْ خَيْرًا مِنْ أَعْمَالِهِمْ وَلَوْ كَانَ ‏ ‏أُحُدٌ ‏ ‏لَكَ ذَهَبًا فَأَنْفَقْتَهُ فِي سَبِيلِ اللَّهِ ثُمَّ لَمْ تُؤْمِنْ بِالْقَدَرِ وَتَعْلَمْ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَأَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ مَا تُقُبِّلَ مِنْكَ وَلَوْ مِتَّ عَلَى غَيْرِ ذَلِكَ دَخَلْتَ النَّارَ ‏ ‏وَلَا عَلَيْكَ أَنْ ‏ ‏تَلْقَى أَخِي ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏فَتَسْأَلَهُ ‏ ‏فَلَقِيَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏ثُمَّ لَقِيَ ‏ ‏حُذَيْفَةَ بْنَ الْيَمَانِ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏ثُمَّ لَقِيَ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مِثْلَ ذَلِكَ إِلَّا أَنَّهُ حَدَّثَهُ عَنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[20667,20667,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي تَارِكٌ فِيكُمْ خَلِيفَتَيْنِ كِتَابُ اللَّهِ وَأَهْلُ بَيْتِي وَإِنَّهُمَا لَنْ ‏ ‏يَتَفَرَّقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ جَمِيعًا ‏","","",""],[20668,20668,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20669,20669,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُمَرَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي ‏ ‏الْعَرِيَّةِ ‏ ‏أَنْ تُؤْخَذَ بِمِثْلِ ‏ ‏خَرْصِهَا ‏ ‏تَمْرًا يَأْكُلُهَا أَهْلُهَا رُطَبًا ‏","","",""],[20670,20670,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏إِلَّا أَنَّهُ رَخَّصَ لِأَهْلِ ‏ ‏الْعَرَايَا ‏ ‏أَنْ يَبِيعُوهَا بِمِثْلِ ‏ ‏خَرْصِهَا ‏","","",""],[20671,20671,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنَا ‏ ‏أَبُو مَسْعُودٍ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏مِنْ ‏ ‏حِيطَانِ ‏ ‏الْمَدِينَةِ ‏ ‏فِيهِ ‏ ‏أَقْبُرٌ ‏ ‏وَهُوَ عَلَى بَغْلَتِهِ ‏ ‏فَحَادَتْ ‏ ‏بِهِ وَكَادَتْ أَنْ تُلْقِيَهُ فَقَالَ مَنْ يَعْرِفُ أَصْحَابَ هَذِهِ ‏ ‏الْأَقْبُرِ ‏ ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ قَوْمٌ هَلَكُوا فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ عَزَّ وَجَلَّ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ثُمَّ قَالَ لَنَا تَعَوَّذُوا بِاللَّهِ مِنْ عَذَابِ جَهَنَّمَ قُلْنَا نَعُوذُ بِاللَّهِ مِنْ عَذَابِ جَهَنَّمَ ثُمَّ قَالَ تَعَوَّذُوا بِاللَّهِ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏فَقُلْنَا نَعُوذُ بِاللَّهِ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏ثُمَّ قَالَ تَعَوَّذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ فَقُلْنَا نَعُوذُ بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ ثُمَّ قَالَ تَعَوَّذُوا بِاللَّهِ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ قُلْنَا نَعُوذُ بِاللَّهِ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ‏","","",""],[20672,20672,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أُمِرْنَا أَنْ نُسَبِّحَ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ تَسْبِيحَةً وَنَحْمَدَ ثَلَاثًا وَثَلَاثِينَ تَحْمِيدَةً وَنُكَبِّرَ أَرْبَعًا وَثَلَاثِينَ تَكْبِيرَةً قَالَ فَرَأَى رَجُلٌ فِي الْمَنَامِ فَقَالَ أُمِرْتُمْ بِثَلَاثٍ وَثَلَاثِينَ تَسْبِيحَةً وَثَلَاثٍ وَثَلَاثِينَ تَحْمِيدَةً وَأَرْبَعٍ وَثَلَاثِينَ تَكْبِيرَةً فَلَوْ جَعَلْتُمْ فِيهَا التَّهْلِيلَ فَجَعَلْتُمُوهَا خَمْسًا وَعِشْرِينَ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَدْ رَأَيْتُمْ فَافْعَلُوا ‏ ‏أَوْ نَحْوَ ذَلِكَ ‏","","",""],[20673,20673,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20674,20674,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُصَلَّى إِذَا طَلَعَ قَرْنُ الشَّمْسِ أَوْ غَابَ قَرْنُهَا وَقَالَ إِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ أَوْ مِنْ بَيْنِ قَرْنَيْ شَيْطَانٍ ‏","","",""],[20675,20675,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَنَحْنُ نَتَبَايَعُ الثِّمَارَ قَبْلَ أَنْ يَبْدُوَ صَلَاحُهَا فَسَمِعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُصُومَةً فَقَالَ مَا هَذَا فَقِيلَ لَهُ هَؤُلَاءِ ابْتَاعُوا الثِّمَارَ يَقُولُونَ أَصَابَنَا ‏ ‏الدُّمَانُ ‏ ‏وَالْقُشَامُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَبَايَعُوهَا حَتَّى يَبْدُوَ صَلَاحُهَا ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَقَالَ ‏ ‏الْأُدْمَانُ ‏ ‏وَالْقُشَامُ ‏","","",""],[20676,20676,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادُ بْنُ سَعْدٍ الْخُرَاسَانِيُّ ‏ ‏سَمِعَ ‏ ‏شُرَحْبِيلَ بْنَ سَعْدٍ ‏ ‏يَقُولُ ‏ ‏أَتَانَا ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَنَحْنُ فِي ‏ ‏حَائِطٍ ‏ ‏لَنَا وَمَعَنَا ‏ ‏فِخَاخٌ ‏ ‏نَنْصِبُ بِهَا فَصَاحَ بِنَا وَطَرَدَنَا وَقَالَ أَلَمْ تَعْلَمُوا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ صَيْدَهَا ‏","","",""],[20677,20677,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏إِنِّي قَاعِدٌ إِلَى جَنْبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا إِذْ أُوحِيَ إِلَيْهِ قَالَ ‏ ‏وَغَشِيَتْهُ ‏ ‏السَّكِينَةُ ‏ ‏وَوَقَعَ فَخِذُهُ عَلَى فَخِذِي حِينَ ‏ ‏غَشِيَتْهُ ‏ ‏السَّكِينَةُ ‏ ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏فَلَا وَاللَّهِ مَا وَجَدْتُ شَيْئًا قَطُّ أَثْقَلَ مِنْ فَخِذِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏سُرِّيَ ‏ ‏عَنْهُ فَقَالَ اكْتُبْ يَا ‏ ‏زَيْدُ ‏ ‏فَأَخَذْتُ ‏ ‏كَتِفًا ‏ ‏فَقَالَ اكْتُبْ ‏ ‏لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ الْآيَةَ كُلَّهَا إِلَى قَوْلِهِ أَجْرًا عَظِيمًا فَكَتَبْتُ ذَلِكَ فِي ‏ ‏كَتِفٍ ‏ ‏فَقَامَ حِينَ سَمِعَهَا ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏وَكَانَ رَجُلًا أَعْمَى فَقَامَ حِينَ سَمِعَ فَضِيلَةَ الْمُجَاهِدِينَ قَالَ يَا رَسُولَ اللَّهِ فَكَيْفَ بِمَنْ لَا يَسْتَطِيعُ الْجِهَادَ مِمَّنْ هُوَ أَعْمَى وَأَشْبَاهِ ذَلِكَ قَالَ ‏ ‏زَيْدٌ ‏ ‏فَوَاللَّهِ مَا مَضَى كَلَامُهُ أَوْ مَا هُوَ إِلَّا أَنْ قَضَى كَلَامَهُ ‏ ‏غَشِيَتْ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّكِينَةُ ‏ ‏فَوَقَعَتْ فَخِذُهُ عَلَى فَخِذِي فَوَجَدْتُ مِنْ ثِقَلِهَا كَمَا وَجَدْتُ فِي الْمَرَّةِ الْأُولَى ثُمَّ ‏ ‏سُرِّيَ ‏ ‏عَنْهُ فَقَالَ اقْرَأْ فَقَرَأْتُ عَلَيْهِ لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏غَيْرُ ‏ ‏أُولِي ‏ ‏الضَّرَرِ ‏} ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏فَأَلْحَقْتُهَا ‏ ‏فَوَاللَّهِ لَكَأَنِّي أَنْظُرُ إِلَى مُلْحَقِهَا عِنْدَ ‏ ‏صَدْعٍ ‏ ‏كَانَ فِي ‏ ‏الْكَتِفِ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ عَلَى رَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا إِلَى جَنْبِهِ فَذَكَرَ نَحْوَهُ ‏","","",""],[20678,20678,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ بْنُ حَبِيبِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَن ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَّمَهُ دُعَاءً وَأَمَرَهُ أَنْ يَتَعَاهَدَ بِهِ أَهْلَهُ كُلَّ يَوْمٍ قَالَ قُلْ كُلَّ يَوْمٍ حِينَ تُصْبِحُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ فِي يَدَيْكَ وَمِنْكَ وَبِكَ وَإِلَيْكَ اللَّهُمَّ مَا قُلْتُ مِنْ قَوْلٍ أَوْ ‏ ‏نَذَرْتُ ‏ ‏مِنْ ‏ ‏نَذْرٍ ‏ ‏أَوْ حَلَفْتُ مِنْ حَلِفٍ فَمَشِيئَتُكَ بَيْنَ يَدَيْهِ مَا شِئْتَ كَانَ وَمَا لَمْ تَشَأْ لَمْ يَكُنْ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ وَمَا صَلَّيْتُ مِنْ صَلَاةٍ فَعَلَى مَنْ صَلَّيْتَ وَمَا لَعَنْتُ مِنْ لَعْنَةٍ فَعَلَى مَنْ لَعَنْتَ إِنَّكَ أَنْتَ ‏ ‏وَلِيِّي ‏ ‏فِي الدُّنْيَا وَالْآخِرَةِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ أَسْأَلُكَ اللَّهُمَّ الرِّضَا بَعْدَ الْقَضَاءِ وَبَرْدَ الْعَيْشِ بَعْدَ الْمَمَاتِ وَلَذَّةَ نَظَرٍ إِلَى وَجْهِكَ وَشَوْقًا إِلَى لِقَائِكَ مِنْ غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا ‏ ‏فِتْنَةٍ ‏ ‏مُضِلَّةٍ أَعُوذُ بِكَ اللَّهُمَّ أَنْ أَظْلِمَ أَوْ أُظْلَمَ أَوْ أَعْتَدِيَ أَوْ ‏ ‏يُعْتَدَى عَلَيَّ أَوْ أَكْتَسِبَ خَطِيئَةً مُحْبِطَةً أَوْ ذَنْبًا لَا يُغْفَرُ اللَّهُمَّ ‏ ‏فَاطِرَ ‏ ‏السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ ذَا ‏ ‏الْجَلَالِ ‏ ‏وَالْإِكْرَامِ فَإِنِّي أَعْهَدُ إِلَيْكَ فِي هَذِهِ الْحَيَاةِ الدُّنْيَا وَأُشْهِدُكَ وَكَفَى بِكَ شَهِيدًا أَنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ لَكَ الْمُلْكُ وَلَكَ الْحَمْدُ وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُكَ وَرَسُولُكَ وَأَشْهَدُ أَنَّ وَعْدَكَ حَقٌّ وَلِقَاءَكَ حَقٌّ وَالْجَنَّةَ حَقٌّ وَالسَّاعَةَ آتِيَةٌ لَا ‏ ‏رَيْبَ ‏ ‏فِيهَا وَأَنْتَ تَبْعَثُ مَنْ فِي الْقُبُورِ وَأَشْهَدُ أَنَّكَ إِنْ ‏ ‏تَكِلْنِي ‏ ‏إِلَى نَفْسِي ‏ ‏تَكِلْنِي ‏ ‏إِلَى ‏ ‏ضَيْعَةٍ ‏ ‏وَعَوْرَةٍ وَذَنْبٍ وَخَطِيئَةٍ وَإِنِّي لَا أَثِقُ إِلَّا بِرَحْمَتِكَ فَاغْفِرْ لِي ذَنْبِي كُلَّهُ إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْدَمَهُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏سُلَيْمَانَ بْنِ دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ أَبِيهِ عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏","","",""],[20679,20679,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَدِمَ رَجُلٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏بِزَيْتٍ ‏ ‏فَسَاوَمْتُهُ ‏ ‏فِيمَنْ ‏ ‏سَاوَمَهُ ‏ ‏مِنْ التُّجَّارِ حَتَّى ‏ ‏ابْتَعْتُهُ ‏ ‏مِنْهُ حَتَّى قَالَ فَقَامَ إِلَيَّ رَجُلٌ فَرَبَّحَنِي فِيهِ حَتَّى أَرْضَانِي قَالَ فَأَخَذْتُ بِيَدِهِ لِأَضْرِبَ عَلَيْهَا فَأَخَذَ رَجُلٌ بِذِرَاعِي مِنْ خَلْفِي فَالْتَفَتُّ إِلَيْهِ فَإِذَا ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏فَقَالَ لَا تَبِعْهُ حَيْثُ ابْتَعْتَهُ حَتَّى تَحُوزَهُ إِلَى رَحْلِكَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَهَى عَنْ ذَلِكَ فَأَمْسَكْتُ يَدِي ‏","","",""],[20680,20680,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏خَارِجَةَ بْنَ زَيْدِ بْنِ ثَابِتٍ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20681,20681,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏فِي الْأَسْوَاقِ وَمَعِي طَيْرٌ اصْطَدْتُهُ قَالَ فَلَطَمَ قَفَايَ وَأَرْسَلَهُ مِنْ يَدِي وَقَالَ أَمَا عَلِمْتَ يَا عَدُوَّ نَفْسِكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏","","",""],[20682,20682,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ بِنَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَتَسَحَّرُ يَأْكُلُ تَمْرًا فَقَالَ تَعَالَ فَكُلْ فَقُلْتُ إِنِّي أُرِيدُ الصَّوْمَ فَقَالَ وَأَنَا أُرِيدُ مَا تُرِيدُ فَأَكَلْنَا ثُمَّ قُمْنَا إِلَى الصَّلَاةِ ‏ ‏فَكَانَ بَيْنَ مَا أَكَلْنَا وَبَيْنَ أَنْ قُمْنَا إِلَى الصَّلَاةِ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً ‏","","",""],[20683,20683,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ بْنُ حُسَينٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُبَاعُ ثَمَرَةٌ بِتَمْرَةٍ وَلَا تُبَاعُ ثَمَرَةٌ حَتَّى يَبْدُوَ صَلَاحُهَا قَالَ فَلَقِيَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فَقَالَ رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي عَرَايَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْعَرَايَا نَخْلٌ كَانَتْ تُوهَبُ لِلْمَسَاكِينِ فَلَا يَسْتَطِيعُونَ أَنْ يَنْتَظِرُوا بِهَا فَيَبِيعُونَهَا بِمَا شَاءُوا مِنْ ثَمَرِهِ ‏","","",""],[20684,20684,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ الشَّهَادَةِ مَا شَهِدَ بِهَا صَاحِبُهَا قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[20685,20685,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ الْمَسَاجِدَ وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏","","",""],[20686,20686,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَشْجَعَ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُوُفِّيَ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏صَلُّوا عَلَى صَاحِبِكُمْ فَتَغَيَّرَ وُجُوهُ النَّاسِ مِنْ ذَلِكَ فَقَالَ إِنَّ صَاحِبَكُمْ ‏ ‏غَلَّ ‏ ‏فِي سَبِيلِ ‏ ‏اللَّهِ ‏ ‏فَفَتَّشْنَا مَتَاعَهُ فَوَجَدْنَا خَرَزًا مِنْ خَرَزِ ‏ ‏يَهُودَ ‏ ‏مَا ‏ ‏يُسَاوِي دِرْهَمَيْنِ ‏","","",""],[20687,20687,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ ‏ ‏أَوْ كُتِبَ لَهُ ‏ ‏مِثْلُ أَجْرِ الصَّائِمِ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَجْرِ الصَّائِمِ شَيْئًا وَمَنْ ‏ ‏جَهَّزَ ‏ ‏غَازِيًا ‏ ‏فِي سَبِيلِ اللَّهِ كَانَ لَهُ ‏ ‏أَوْ كُتِبَ لَهُ ‏ ‏مِثْلُ أَجْرِ ‏ ‏الْغَازِي ‏ ‏فِي أَنَّهُ لَا يَنْقُصُ مِنْ أَجْرِ ‏ ‏الْغَازِي ‏ ‏شَيْئًا ‏","","",""],[20688,20688,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا فِي بُيُوتِكُمْ وَلَا تَتَّخِذُوهَا قُبُورًا ‏","","",""],[20689,20689,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي لَبِيدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مُرْ أَصْحَابَكَ فَلْيَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ فَإِنَّهَا مِنْ شَعَائِرِ الْحَجِّ ‏","","",""],[20690,20690,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا الدِّيكَ فَإِنَّهُ يَدْعُو إِلَى الصَّلَاةِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ سَبِّ الدِّيكِ وَقَالَ إِنَّهُ يُؤَذِّنُ بِالصَّلَاةِ ‏","","",""],[20691,20691,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏لَأَرْمُقَنَّ ‏ ‏اللَّيْلَةَ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَسَّدْتُ ‏ ‏عَتَبَتَهُ ‏ ‏أَوْ ‏ ‏فُسْطَاطَهُ ‏ ‏فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ صَلَّى رَكْعَتَيْنِ طَوِيلَتَيْنِ ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ صَلَّى رَكْعَتَيْنِ دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ صَلَّى رَكْعَتَيْنِ دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ صَلَّى رَكْعَتَيْنِ دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ ‏ ‏أَوْتَرَ ‏ ‏فَذَلِكَ ثَلَاثَ عَشْرَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏مُصْعَبٌ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسِ بْنِ مَخْرَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏فِي حَدِيثِ ‏ ‏مَالِكٍ ‏ ‏عَنْ أَبِيهِ وَالصَّوَابُ مَا رَوَى ‏ ‏مُصْعَبٌ ‏ ‏عَنْ أَبِيهِ ‏ ‏وَكَذَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسِ بْنِ مَخْرَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏وَالصَّوَابُ مَا قَالَ ‏ ‏مُصْعَبٌ ‏ ‏ومَعْنٌ ‏ ‏عَنْ أَبِيهِ وَلَمْ يَذْكُرْ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فِيهِ عَنْ أَبِيهِ وَهِمَ فِيهِ ‏","","",""],[20692,20692,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏بُسْرُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ خَالِدٍ الْجُهَنِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَهَّزَ ‏ ‏غَازِيًا ‏ ‏فَقَدْ غَزَا وَمَنْ خَلَفَ ‏ ‏غَازِيًا ‏ ‏فِي أَهْلِهِ بِخَيْرٍ فَقَدْ غَزَا ‏","","",""],[20693,20693,"","","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيٌّ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ الْمَسَاجِدَ وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏","","",""],[20694,20694,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَمْرَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ الشُّهَدَاءِ الَّذِي يَأْتِي بِشَهَادَتِهِ قَبْلَ أَنْ يُسْأَلَهَا أَوْ يُخْبِرُ بِشَهَادَتِهِ قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[20695,20695,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏زَيْدٌ ‏ ‏يَرُوحُ إِلَى الْمَسْجِدِ وَسِوَاكُهُ عَلَى أُذُنِهِ بِمَوْضِعِ قَلَمِ الْكَاتِبِ مَا تُقَامُ صَلَاةٌ إِلَّا اسْتَاكَ قَبْلَ أَنْ يُصَلِّيَ ‏","","",""],[20696,20696,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِجُهَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏النُّهْبَةِ ‏ ‏وَالْخُلْسَةِ ‏","","",""],[20697,20697,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَن ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ ‏ ‏اللُّقَطَةِ ‏ ‏فَقَالَ ‏ ‏عَرِّفْهَا ‏ ‏سَنَةً فَإِنْ جَاءَ ‏ ‏بَاغِيهَا ‏ ‏فَأَدِّهَا إِلَيْهِ وَإِلَّا فَاعْرِفْ ‏ ‏عِفَاصَهَا ‏ ‏وَوِكَاءَهَا ‏ ‏ثُمَّ كُلْهَا فَإِنْ جَاءَ ‏ ‏بَاغِيهَا ‏ ‏فَأَدِّهَا إِلَيْهِ ‏","","",""],[20698,20698,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏أُبَيُّ بْنُ عَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏حَدَّثَنِي ‏ ‏خَارِجَةُ بْنُ زَيْدِ بْنِ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ خَالِدٍ الْجُهَنِيُّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُ الشُّهُودِ مَنْ أَدَّى شَهَادَتَهُ قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[20699,20699,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنِي ‏ ‏يَعْقُوبُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَلَا أَعْلَمُهُ إِلَّا أَنَّهُ قَالَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قُرَيْشٌ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏أَوْ ‏ ‏غِفَارٌ ‏ ‏وَأَسْلَمُ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏أَشْجَعَ ‏ ‏وَجُهَيْنَةَ ‏ ‏أَوْ ‏ ‏جُهَيْنَةَ ‏ ‏وَأَشْجَعَ ‏ ‏حُلَفَاءُ ‏ ‏مَوَالِيَّ لَيْسَ لَهُمْ مِنْ دُونِ اللَّهِ وَلَا رَسُولِهِ ‏ ‏مَوْلًى ‏","","",""],[20700,20700,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَسَّ فَرْجَهُ فَلْيَتَوَضَّأْ ‏","","",""],[20701,20701,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ بْنُ عَبْدِ اللَّهِ بْنِ طُعْمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَصْحَابِهِ غَنَمًا لِلضَّحَايَا ‏ ‏فَأَعْطَانِي ‏ ‏عَتُودًا ‏ ‏جَذَعًا ‏ ‏مِنْ الْمَعْزِ قَالَ فَجِئْتُهُ بِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُ ‏ ‏جَذَعٌ ‏ ‏قَالَ ضَحِّ بِهِ فَضَحَّيْتُ بِهِ ‏","","",""],[20702,20702,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الدَّرَاوَرْدِيَّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى سَجْدَتَيْنِ لَا ‏ ‏يَسْهُو فِيهِمَا غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[20703,20703,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏عُمَرَ الدِّمَشْقِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏قَالَتْ حَدَّثَنِي ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏أَنَّهُ ‏ ‏سَجَدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَى عَشْرَةَ سَجْدَةً مِنْهُنَّ ‏ ‏النَّجْمُ ‏","","",""],[20704,20704,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي زَكَرِيَّا الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ تُدْعَوْنَ يَوْمَ الْقِيَامَةِ بِأَسْمَائِكُمْ وَأَسْمَاءِ آبَائِكُمْ فَحَسِّنُوا أَسْمَاءَكُمْ ‏","","",""],[20705,20705,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي مَرْيَمَ الْغَسَّانِيُّ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مُحَمَّدٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُبُّكَ ‏ ‏الشَّيْءَ ‏ ‏يُعْمِي وَيُصِمُّ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو الْيَمَانِ ‏ ‏لَمْ يَرْفَعْهُ ‏ ‏وَرَفَعَهُ ‏ ‏الْقُرْقُسَانِيُّ مُحَمَّدُ بْنُ مُصْعَبٍ ‏","","",""],[20706,20706,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مِنْ ‏ ‏فِقْهِ ‏ ‏الرَّجُلِ رِفْقُهُ فِي مَعِيشَتِهِ ‏","","",""],[20707,20707,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ وَإِنَّ أَحَدَنَا لَيَضَعُ يَدَهُ عَلَى رَأْسِهِ مِنْ شِدَّةِ الْحَرِّ ‏ ‏وَمَا مِنَّا صَائِمٌ إِلَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏","","",""],[20708,20708,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي ثَابِتٍ ‏ ‏أَنَّ رَجُلًا دَخَلَ مَسْجِدَ ‏ ‏دِمَشْقَ ‏ ‏فَقَالَ اللَّهُمَّ آنِسْ وَحْشَتِي وَارْحَمْ غُرْبَتِي وَارْزُقْنِي جَلِيسًا صَالِحًا فَسَمِعَهُ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏فَقَالَ لَئِنْ كُنْتَ صَادِقًا لَأَنَا أَسْعَدُ بِمَا قُلْتَ مِنْكَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ { ‏فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ ‏} ‏يَعْنِي الظَّالِمَ ‏ ‏يُؤْخَذُ مِنْهُ فِي مَقَامِهِ ذَلِكَ فَذَلِكَ الْهَمُّ وَالْحَزَنُ ‏ { ‏وَمِنْهُمْ ‏ ‏مُقْتَصِدٌ ‏ } ‏قَالَ يُحَاسَبُ حِسَابًا يَسِيرًا ‏ { ‏وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِإِذْنِ اللَّهِ ‏} ‏قَالَ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ ‏","","",""],[20709,20709,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ حَيَّانَ الدِّمَشْقِيِّ ‏ ‏أَخْبَرَتْنِي ‏ ‏أُمُّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ فِي الْيَوْمِ الْحَارِّ الشَّدِيدِ الْحَرِّ ‏ ‏حَتَّى إِنَّ الرَّجُلَ لَيَضَعُ يَدَهُ عَلَى رَأْسِهِ فِي شِدَّةِ الْحَرِّ ‏ ‏وَمَا فِي الْقَوْمِ صَائِمٌ إِلَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏","","",""],[20710,20710,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ الْقُرْدُوسِيُّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ إِعْطَاءِ السُّلْطَانِ قَالَ مَا آتَاكَ اللَّهُ مِنْهُ مِنْ غَيْرِ مَسْأَلَةٍ وَلَا إِشْرَافٍ فَخُذْهُ وَتَمَوَّلْهُ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏الْحَسَنُ ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏لَا بَأْسَ بِهَا مَا لَمْ تَرْحَلْ إِلَيْهَا أَوْ تَشَرَّفْ لَهَا ‏","","",""],[20711,20711,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيْهَا يَوْمًا ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏مُغْضَبًا فَقَالَتْ مَا لَكَ قَالَ وَاللَّهِ ‏ ‏مَا أَعْرِفُ فِيهِمْ شَيْئًا مِنْ أَمْرِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا أَنَّهُمْ يُصَلُّونَ جَمِيعًا ‏","","",""],[20712,20712,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏أَوْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ ‏ ‏قَالَ ‏ ‏فَلَقِيتُ ‏ ‏ثَوْبَانَ ‏ ‏فِي ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ ‏ ‏فَقَالَ ‏ ‏أَنَا صَبَبْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضُوءَهُ ‏","","",""],[20713,20713,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏حَدَّثَنِي ‏ ‏مَوْلَى ابْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي بَحْرِيَّةَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي بَحْرِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ ‏ ‏قَالَ ‏ ‏مَكِّيٌّ ‏ ‏وَأَزْكَاهَا ‏ ‏عِنْدَ مَلِيكِكُمْ وَأَرْفَعِهَا فِي دَرَجَاتِكُمْ وَخَيْرٍ لَكُمْ مِنْ إِعْطَاءِ الذَّهَبِ ‏ ‏وَالْوَرِقِ ‏ ‏وَخَيْرٍ لَكُمْ مِنْ أَنْ تَلْقَوْا عَدُوَّكُمْ فَتَضْرِبُوا أَعْنَاقَهُمْ وَيَضْرِبُوا أَعْنَاقَكُمْ قَالُوا وَذَلِكَ مَا هُوَ يَا رَسُولَ اللَّهِ قَالَ ذِكْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[20714,20714,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى امْرَأَةً ‏ ‏مُجِحًّا ‏ ‏عَلَى بَابِ ‏ ‏فُسْطَاطٍ ‏ ‏أَوْ طَرَفِ ‏ ‏فُسْطَاطٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّ صَاحِبَهَا يُلِمُّ بِهَا قَالُوا نَعَمْ قَالَ لَقَدْ هَمَمْتُ أَنْ أَلْعَنَهُ لَعْنَةً تَدْخُلُ مَعَهُ فِي قَبْرِهِ كَيْفَ يُوَرِّثُهُ وَهُوَ لَا يَحِلُّ لَهُ وَكَيْفَ يَسْتَخْدِمُهَا وَهُوَ لَا يَحِلُّ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادُ بْنُ أَبِي زِيَادٍ ‏ ‏حَدِيثًا يَرْفَعُهُ إِلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ فَذَكَرَ الْحَدِيثَ ‏ ‏يَعْنِي حَدِيثَ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏وَمَكِّيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي زِيَادٍ ‏","","",""],[20715,20715,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيَعْجَبُ أَحَدُكُمْ أَنْ يَقْرَأَ ثُلُثَ الْقُرْآنِ فِي لَيْلَةٍ قَالُوا كَيْفَ يُطِيقُ ذَلِكَ ‏ ‏أَوْ مَنْ يُطِيقُ ذَلِكَ ‏ ‏قَالَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[20716,20716,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏عَنْ الضَّبُعِ فَكَرِهَهَا فَقُلْتُ لَهُ إِنَّ قَوْمَكَ يَأْكُلُونَهُ قَالَ لَا يَعْلَمُونَ ‏ ‏فَقَالَ ‏ ‏رَجُلٌ ‏ ‏عِنْدَهُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ كُلِّ ذِي ‏ ‏نُهْبَةٍ ‏ ‏وَكُلِّ ذِي ‏ ‏خَطْفَةٍ ‏ ‏وَكُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏صَدَقَ ‏","","",""],[20717,20717,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏قَالَ ‏ ‏وَكَانَتْ تَحْتَهُ ‏ ‏الدَّرْدَاءُ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏الشَّامَ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏فَلَمْ أَجِدْهُ وَوَجَدْتُ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏فَقَالَتْ تُرِيدُ الْحَجَّ الْعَامَ قَالَ قُلْتُ نَعَمْ فَقَالَتْ فَادْعُ لَنَا بِخَيْرٍ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ دَعْوَةَ الْمُسْلِمِ مُسْتَجَابَةٌ لِأَخِيهِ بِظَهْرِ الْغَيْبِ عِنْدَ رَأْسِهِ مَلَكٌ مُوَكَّلٌ كُلَّمَا دَعَا لِأَخِيهِ بِخَيْرٍ قَالَ آمِينَ وَلَكَ بِمِثْلٍ ‏ ‏فَخَرَجْتُ إِلَى السُّوقِ فَأَلْقَى ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏مِثْلَ ذَلِكَ يَأْثُرُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَيَعْلَى ‏ ‏قَالَا ثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏صَفْوَانَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏ابْنُ عَبْدِ اللَّهِ ‏ ‏فَذَكَرَهُ ‏","","",""],[20718,20718,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏نَزَلَ ‏ ‏بِأَبِي الدَّرْدَاءِ ‏ ‏رَجُلٌ فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏مُقِيمٌ فَنَسْرَحَ أَمْ ‏ ‏ظَاعِنٌ ‏ ‏فَنَعْلِفَ قَالَ بَلْ ‏ ‏ظَاعِنٌ ‏ ‏قَالَ فَإِنِّي سَأُزَوِّدُكَ زَادًا لَوْ أَجِدُ مَا هُوَ أَفْضَلُ مِنْهُ لَزَوَّدْتُكَ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ذَهَبَ الْأَغْنِيَاءُ بِالدُّنْيَا وَالْآخِرَةِ نُصَلِّي وَيُصَلُّونَ وَنَصُومُ وَيَصُومُونَ وَيَتَصَدَّقُونَ وَلَا نَتَصَدَّقُ قَالَ ‏ ‏أَلَا أَدُلُّكَ عَلَى شَيْءٍ إِنْ أَنْتَ فَعَلْتَهُ لَمْ يَسْبِقْكَ أَحَدٌ كَانَ قَبْلَكَ وَلَمْ يُدْرِكْكَ أَحَدٌ بَعْدَكَ إِلَّا مَنْ فَعَلَ الَّذِي تَفْعَلُ ‏ ‏دُبُرَ ‏ ‏كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ تَسْبِيحَةً وَثَلَاثًا وَثَلَاثِينَ تَحْمِيدَةً وَأَرْبَعًا وَثَلَاثِينَ تَكْبِيرَةً ‏","","",""],[20719,20719,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏زَائِدَةُ بْنُ قُدَامَةَ ‏ ‏حَدَّثَنِي ‏ ‏السَّائِبُ بْنُ حُبَيْشٍ الْكَلَاعِيُّ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏أَيْنَ مَسْكَنُكَ قَالَ قُلْتُ فِي قَرْيَةٍ دُونَ ‏ ‏حِمْصَ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ ثَلَاثَةٍ فِي قَرْيَةٍ لَا يُؤَذَّنُ وَلَا تُقَامُ فِيهِمْ الصَّلَاةُ إِلَّا اسْتَحْوَذَ عَلَيْهِمْ الشَّيْطَانُ فَعَلَيْكَ بِالْجَمَاعَةِ فَإِنَّ الذِّئْبَ يَأْكُلُ ‏ ‏الْقَاصِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَيْضًا ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏السَّائِبُ بْنُ حُبَيْشٍ الْكَلَاعِيُّ ‏ ‏فَذَكَرَهُ ‏","","",""],[20720,20720,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ ‏ ‏الْكَهْفِ ‏ ‏عُصِمَ مِنْ ‏ ‏الدَّجَّالِ ‏","","",""],[20721,20721,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَأَةَ ‏ ‏عَنْ ‏ ‏ابْنِ نُعْمَانَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ضَحَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَبْشَيْنِ ‏ ‏جَذَعَيْنِ ‏ ‏مُوجِبَيْنِ ‏","","",""],[20722,20722,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ نُعْمَانَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ضَحَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَبْشَيْنِ ‏ ‏جَذَعَيْنِ ‏ ‏خَصِيَّيْنِ ‏","","",""],[20723,20723,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏أَنَا ‏ ‏عَاصِمُ بْنُ رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَجُلٌ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏وَهُوَ ‏ ‏بِدِمَشْقَ ‏ ‏فَقَالَ مَا أَقْدَمَكَ أَيْ أَخِي قَالَ حَدِيثٌ بَلَغَنِي أَنَّكَ تُحَدِّثُ بِهِ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَمَا قَدِمْتَ لِتِجَارَةٍ قَالَ لَا قَالَ أَمَا قَدِمْتَ لِحَاجَةٍ قَالَ لَا قَالَ مَا قَدِمْتَ إِلَّا فِي طَلَبِ هَذَا الْحَدِيثِ قَالَ نَعَمْ قَالَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَلَكَ اللَّهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ وَإِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا رِضًا لِطَالِبِ الْعِلْمِ وَإِنَّهُ لَيَسْتَغْفِرُ لِلْعَالِمِ مَنْ فِي السَّمَوَاتِ وَالْأَرْضِ حَتَّى الْحِيتَانُ فِي الْمَاءِ وَفَضْلُ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِ الْقَمَرِ عَلَى سَائِرِ الْكَوَاكِبِ إِنَّ الْعُلَمَاءَ هُمْ وَرَثَةُ الْأَنْبِيَاءِ لَمْ يَرِثُوا دِينَارًا وَلَا دِرْهَمًا وَإِنَّمَا وَرِثُوا الْعِلْمَ فَمَنْ أَخَذَهُ أَخَذَ بِحَظٍّ وَافِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ جَمِيلٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏أَقْبَلَ رَجُلٌ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[20724,20724,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ السُّلَمِيَّ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَجُلًا أَمَرَتْهُ أُمُّهُ ‏ ‏أَوْ أَبُوهُ أَوْ كِلَاهُمَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏يَقُولُ ذَلِكَ ‏ ‏أَنْ يُطَلِّقَ امْرَأَتَهُ فَجَعَلَ عَلَيْهِ مِائَةَ مُحَرَّرٍ فَأَتَى ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَإِذَا هُوَ ‏ ‏يُصَلِّي الضُّحَى يُطِيلُهَا وَصَلَّى مَا بَيْنَ الظُّهْرِ وَالْعَصْرِ فَسَأَلَهُ فَقَالَ لَهُ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏أَوْفِ نَذْرَكَ وَبَرَّ وَالِدَيْكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْوَالِدُ أَوْسَطُ بَابِ الْجَنَّةِ فَحَافِظْ عَلَى الْوَالِدِ أَوْ اتْرُكْ ‏","","",""],[20725,20725,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا حَبِيبَةَ ‏ ‏قَالَ ‏ ‏أَوْصَى رَجُلٌ بِدَنَانِيرَ فِي سَبِيلِ اللَّهِ فَسُئِلَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏فَحَدَّثَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَثَلُ الَّذِي يُعْتِقُ أَوْ يَتَصَدَّقُ عِنْدَ مَوْتِهِ مَثَلُ الَّذِي يُهْدِي بَعْدَمَا يَشْبَعُ ‏ ‏قَالَ ‏ ‏أَبُو حَبِيبَةَ ‏ ‏فَأَصَابَنِي مِنْ ذَلِكَ شَيْءٌ ‏","","",""],[20726,20726,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَبِيبَةَ الطَّائِيِّ ‏ ‏قَالَ ‏ ‏أَوْصَى إِلَيَّ أَخِي بِطَائِفَةٍ مِنْ مَالِهِ قَالَ فَلَقِيتُ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَقُلْتُ إِنَّ أَخِي أَوْصَانِي بِطَائِفَةٍ مِنْ مَالِهِ فَأَيْنَ أَضَعُهُ فِي الْفُقَرَاءِ أَوْ فِي الْمُجَاهِدِينَ أَوْ فِي الْمَسَاكِينَ قَالَ أَمَّا أَنَا فَلَوْ كُنْتُ لَمْ أَعْدِلْ بِالْمُجَاهِدِينَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ الَّذِي يُعْتِقُ عِنْدَ الْمَوْتِ مَثَلُ الَّذِي يُهْدِي إِذَا شَبِعَ ‏","","",""],[20727,20727,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَفِي كُلِّ صَلَاةٍ قِرَاءَةٌ قَالَ نَعَمْ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَجَبَتْ هَذِهِ ‏","","",""],[20728,20728,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خُلَيْدٍ الْعَصَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا طَلَعَتْ شَمْسٌ قَطُّ إِلَّا بُعِثَ بِجَنْبَتَيْهَا مَلَكَانِ يُنَادِيَانِ يُسْمِعَانِ أَهْلَ الْأَرْضِ إِلَّا ‏ ‏الثَّقَلَيْنِ ‏ ‏يَا أَيُّهَا النَّاسُ هَلُمُّوا إِلَى رَبِّكُمْ فَإِنَّ مَا قَلَّ وَكَفَى خَيْرٌ مِمَّا كَثُرَ وَأَلْهَى وَلَا ‏ ‏آبَتْ ‏ ‏شَمْسٌ قَطُّ إِلَّا بُعِثَ بِجَنْبَتَيْهَا مَلَكَانِ يُنَادِيَانِ يُسْمِعَانِ أَهْلَ الْأَرْضِ إِلَّا ‏ ‏الثَّقَلَيْنِ ‏ ‏اللَّهُمَّ أَعْطِ مُنْفِقًا ‏ ‏خَلَفًا ‏ ‏وَأَعْطِ مُمْسِكًا مَالًا ‏ ‏تَلَفًا ‏","","",""],[20729,20729,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي حَلْبَسٍ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ فَرَغَ إِلَى كُلِّ عَبْدٍ مِنْ خَلْقِهِ مِنْ خَمْسٍ مِنْ أَجَلِهِ وَعَمَلِهِ وَمَضْجَعِهِ وَأَثَرِهِ وَرِزْقِهِ ‏","","",""],[20730,20730,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ صُبَيْحٍ الْمُرِّيُّ ‏ ‏قَاضِي ‏ ‏الْبَلْقَاءِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تُحَدِّثُ عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَرَغَ اللَّهُ إِلَى كُلِّ عَبْدٍ مِنْ خَمْسٍ مِنْ أَجَلِهِ وَرِزْقِهِ وَأَثَرِهِ وَشَقِيٍّ أَمْ سَعِيدٍ ‏","","",""],[20731,20731,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامٍ ‏ ‏حَدَّثَنَا ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ غَنْمٍ ‏ ‏أَنَّهُ ‏ ‏زَارَ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏بِحِمْصَ ‏ ‏فَمَكَثَ عِنْدَهُ ‏ ‏لَيَالِيَ وَأَمَرَ بِحِمَارِهِ ‏ ‏فَأُوكِفَ ‏ ‏فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏مَا أَرَانِي إِلَّا مُتَّبِعَكَ فَأَمَرَ بِحِمَارِهِ فَأُسْرِجَ فَسَارَا جَمِيعًا عَلَى حِمَارَيْهِمَا فَلَقِيَا رَجُلًا شَهِدَ الْجُمُعَةَ بِالْأَمْسِ عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏بِالْجَابِيَةِ ‏ ‏فَعَرَفَهُمَا الرَّجُلُ وَلَمْ يَعْرِفَاهُ فَأَخْبَرَهُمَا خَبَرَ النَّاسِ ثُمَّ إِنَّ الرَّجُلَ قَالَ وَخَبَرٌ آخَرُ كَرِهْتُ أَنْ أُخْبِرَكُمَا أُرَاكُمَا تَكْرَهَانِهِ فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏فَلَعَلَّ ‏ ‏أَبَا ذَرٍّ ‏ ‏نُفِيَ قَالَ نَعَمْ وَاللَّهِ فَاسْتَرْجَعَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏وَصَاحِبُهُ قَرِيبًا مِنْ عَشْرِ مَرَّاتٍ ثُمَّ قَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏ارْتَقِبْهُمْ وَاصْطَبِرْ كَمَا قِيلَ لِأَصْحَابِ النَّاقَةِ اللَّهُمَّ إِنْ كَذَّبُوا ‏ ‏أَبَا ذَرٍّ ‏ ‏فَإِنِّي لَا أُكَذِّبُهُ اللَّهُمَّ وَإِنْ اتَّهَمُوهُ فَإِنِّي لَا أَتَّهِمُهُ اللَّهُمَّ وَإِنْ ‏ ‏اسْتَغَشُّوهُ ‏ ‏فَإِنِّي لَا ‏ ‏أَسْتَغِشُّهُ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْتَمِنُهُ حِينَ لَا يَأْتَمِنُ أَحَدًا وَيُسِرُّ إِلَيْهِ حِينَ لَا يُسِرُّ إِلَى أَحَدٍ أَمَا وَالَّذِي نَفْسُ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏بِيَدِهِ لَوْ أَنَّ ‏ ‏أَبَا ذَرٍّ ‏ ‏قَطَعَ يَمِينِي مَا أَبْغَضْتُهُ بَعْدَ الَّذِي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أَظَلَّتْ ‏ ‏الْخَضْرَاءُ ‏ ‏وَلَا ‏ ‏أَقَلَّتْ ‏ ‏الْغَبْرَاءُ ‏ ‏مِنْ ذِي لَهْجَةٍ أَصْدَقَ مِنْ ‏ ‏أَبِي ذَرٍّ ‏","","",""],[20732,20732,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ أَرْطَاةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جُبَيْرَ بْنَ نُفَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فُسْطَاطُ ‏ ‏الْمُسْلِمِينَ يَوْمَ ‏ ‏الْمَلْحَمَةِ ‏ ‏الْغُوطَةُ ‏ ‏إِلَى جَانِبِ مَدِينَةٍ يُقَالُ لَهَا ‏ ‏دِمَشْقُ ‏","","",""],[20733,20733,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَقَالَ إِنَّ امْرَأَتِي بِنْتُ عَمِّي وَأَنَا أُحِبُّهَا وَإِنَّ وَالِدَتِي تَأْمُرُنِي أَنْ أُطَلِّقَهَا فَقَالَ لَا آمُرُكَ أَنْ تُطَلِّقَهَا وَلَا آمُرُكَ أَنْ تَعْصِيَ وَالِدَتَكَ وَلَكِنْ أُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْوَالِدَةَ أَوْسَطُ أَبْوَابِ الْجَنَّةِ فَإِنْ شِئْتَ فَأَمْسِكْ وَإِنْ شِئْتَ فَدَعْ ‏","","",""],[20734,20734,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏أَنَسُ بْنُ عِيَاضٍ اللَّيْثِيُّ أَبُو ضَمْرَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ الْأَزْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ وَمِنْهُمْ ‏ ‏مُقْتَصِدٌ ‏ ‏وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِإِذْنِ اللَّهِ ‏} ‏فَأَمَّا الَّذِينَ سَبَقُوا بِالْخَيْرَاتِ فَأُولَئِكَ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَأَمَّا الَّذِينَ اقْتَصَدُوا فَأُولَئِكَ يُحَاسَبُونَ حِسَابًا يَسِيرًا وَأَمَّا الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ فَأُولَئِكَ الَّذِينَ يُحْبَسُونَ فِي طُولِ الْمَحْشَرِ ثُمَّ هُمْ الَّذِينَ تَلَافَاهُمْ اللَّهُ بِرَحْمَتِهِ فَهُمْ الَّذِينَ يَقُولُونَ ‏ { ‏الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ ‏ ‏إِلَى قَوْلِهِ ‏ ‏لُغُوبٌ ‏ }","","",""],[20735,20735,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏فَقَالَ بِالصِّحَّةِ لَا بِالْمَرَضِ فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الصُّدَاعَ ‏ ‏وَالْمَلِيلَةَ ‏ ‏لَا تَزَالُ بِالْمُؤْمِنِ وَإِنَّ ذَنْبَهُ مِثْلُ ‏ ‏أُحُدٍ ‏ ‏فَمَا تَدَعُهُ وَعَلَيْهِ مِنْ ذَلِكَ مِثْقَالُ حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏","","",""],[20736,20736,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَرْبِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَلَبِسَ ثِيَابَهُ وَمَسَّ طِيبًا إِنْ كَانَ عِنْدَهُ ثُمَّ مَشَى إِلَى الْجُمُعَةِ وَعَلَيْهِ السَّكِينَةُ وَلَمْ يَتَخَطَّ أَحَدًا وَلَمْ يُؤْذِهِ وَرَكَعَ مَا قُضِيَ لَهُ ثُمَّ انْتَظَرَ حَتَّى يَنْصَرِفَ الْإِمَامُ غُفِرَ لَهُ مَا بَيْنَ الْجُمُعَتَيْنِ ‏","","",""],[20737,20737,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَرْبِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا عَلَى الْمِنْبَرِ فَخَطَبَ النَّاسَ وَتَلَا آيَةً وَإِلَى جَنْبِي ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏فَقُلْتُ لَهُ يَا ‏ ‏أُبَيُّ ‏ ‏مَتَى أُنْزِلَتْ هَذِهِ الْآيَةُ قَالَ فَأَبَى أَنْ يُكَلِّمَنِي ثُمَّ سَأَلْتُهُ فَأَبَى أَنْ يُكَلِّمَنِي حَتَّى نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي ‏ ‏أُبَيٌّ ‏ ‏مَا لَكَ مِنْ جُمُعَتِكَ إِلَّا مَا ‏ ‏لَغَيْتَ فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِئْتُهُ فَأَخْبَرْتُهُ فَقُلْتُ أَيْ رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تَلَوْتَ آيَةً وَإِلَى جَنْبِي ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏فَسَأَلْتُهُ مَتَى أُنْزِلَتْ هَذِهِ الْآيَةُ فَأَبَى أَنْ يُكَلِّمَنِي حَتَّى إِذَا نَزَلْتَ زَعَمَ ‏ ‏أُبَيٌّ ‏ ‏أَنَّهُ لَيْسَ لِي مِنْ جُمُعَتِي إِلَّا مَا ‏ ‏لَغَيْتُ فَقَالَ صَدَقَ ‏ ‏أُبَيٌّ ‏ ‏فَإِذَا سَمِعْتَ إِمَامَكَ يَتَكَلَّمُ فَأَنْصِتْ حَتَّى يَفْرُغَ ‏","","",""],[20738,20738,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَبْغُونِي ‏ ‏ضُعَفَاءَكُمْ فَإِنَّكُمْ إِنَّمَا تُرْزَقُونَ وَتُنْصَرُونَ بِضُعَفَائِكُمْ ‏","","",""],[20739,20739,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُمَرَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏يُكَنَّى ‏ ‏أَبَا عَبْدِ الصَّمَدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تَقُولُ ‏ ‏كَانَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏إِذَا حَدَّثَ حَدِيثًا تَبَسَّمَ فَقُلْتُ لَا يَقُولُ النَّاسُ إِنَّكَ أَيْ أَحْمَقُ فَقَالَ مَا رَأَيْتُ ‏ ‏أَوْ ‏ ‏مَا سَمِعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُ حَدِيثًا إِلَّا تَبَسَّمَ ‏","","",""],[20740,20740,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَاقِدٍ ‏ ‏حَدَّثَنِي ‏ ‏بُسْرُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِدْرِيسَ الْخَوْلَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا أَنَا نَائِمٌ إِذْ رَأَيْتُ عَمُودَ الْكِتَابِ احْتُمِلَ مِنْ تَحْتِ رَأْسِي فَظَنَنْتُ أَنَّهُ مَذْهُوبٌ بِهِ فَأَتْبَعْتُهُ بَصَرِي فَعُمِدَ بِهِ إِلَى ‏ ‏الشَّامِ ‏ ‏أَلَا وَإِنَّ الْإِيمَانَ حِينَ تَقَعُ الْفِتَنُ ‏ ‏بِالشَّامِ ‏","","",""],[20741,20741,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ ثَابِتِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏عُمَيْرِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَذْرَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجِلُّوا اللَّهَ يَغْفِرْ لَكُمْ ‏ ‏قَالَ ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏يَعْنِي أَسْلِمُوا ‏","","",""],[20742,20742,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُمَرَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الصَّمَدِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏لَا يُحَدِّثُ بِحَدِيثٍ إِلَّا تَبَسَّمَ فِيهِ فَقُلْتُ لَهُ إِنِّي أَخْشَى أَنْ يُحَمِّقَكَ النَّاسُ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُحَدِّثُ بِحَدِيثٍ إِلَّا تَبَسَّمَ ‏","","",""],[20743,20743,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَبَّانُ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّهُ أَتَاهُ ‏ ‏عَائِدًا ‏ ‏فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏لِأَبِي بَعْدَ أَنْ سَلَّمَ عَلَيْهِ بِالصِّحَّةِ لَا بِالْوَجَعِ ثَلَاثَ مَرَّاتٍ يَقُولُ ذَلِكَ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا يَزَالُ الْمَرْءُ الْمُسْلِمُ بِهِ ‏ ‏الْمَلِيلَةُ ‏ ‏وَالصُّدَاعُ وَإِنَّ عَلَيْهِ مِنْ الْخَطَايَا لَأَعْظَمَ مِنْ ‏ ‏أُحُدٍ ‏ ‏حَتَّى يَتْرُكَهُ وَمَا عَلَيْهِ مِنْ الْخَطَايَا مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ ‏","","",""],[20744,20744,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوَّلُ مَنْ يُؤْذَنُ لَهُ بِالسُّجُودِ يَوْمَ الْقِيَامَةِ وَأَنَا أَوَّلُ مَنْ يُؤْذَنُ لَهُ أَنْ يَرْفَعَ رَأْسَهُ فَأَنْظُرَ إِلَى بَيْنِ يَدَيَّ فَأَعْرِفَ أُمَّتِي مِنْ بَيْنِ الْأُمَمِ وَمِنْ خَلْفِي مِثْلُ ذَلِكَ وَعَنْ يَمِينِي مِثْلُ ذَلِكَ وَعَنْ شِمَالِي مِثْلُ ذَلِكَ فَقَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ كَيْفَ تَعْرِفُ أُمَّتَكَ مِنْ بَيْنِ الْأُمَمِ فِيمَا بَيْنَ ‏ ‏نُوحٍ ‏ ‏إِلَى أُمَّتِكَ قَالَ هُمْ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلُونَ ‏ ‏مِنْ أَثَرِ الْوُضُوءِ لَيْسَ أَحَدٌ كَذَلِكَ غَيْرَهُمْ وَأَعْرِفُهُمْ أَنَّهُمْ يُؤْتَوْنَ كُتُبَهُمْ بِأَيْمَانِهِمْ وَأَعْرِفُهُمْ ‏ ‏يَسْعَى بَيْنَ أَيْدِيهِمْ ذُرِّيَّتُهُمْ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏شَكَّ فِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا ذَرٍّ ‏ ‏أَوْ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَيَقُولُ ‏ ‏فَأَعْرِفُهُمْ أَنَّ نُورَهُمْ ‏ ‏يَسْعَى بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا ذَرٍّ ‏ ‏أَوْ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوَّلُ مَنْ يُؤْذَنُ لَهُ فِي السُّجُودِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[20745,20745,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مِنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏وَأَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَعْرِفُ أُمَّتِي يَوْمَ الْقِيَامَةِ مِنْ بَيْنِ الْأُمَمِ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ تَعْرِفُ أُمَّتَكَ قَالَ أَعْرِفُهُمْ يُؤْتَوْنَ كُتُبَهُمْ بِأَيْمَانِهِمْ وَأَعْرِفُهُمْ ‏ ‏بِسِيمَاهُمْ ‏ ‏فِي وُجُوهِهِمْ مِنْ أَثَرِ السُّجُودِ وَأَعْرِفُهُمْ بِنُورِهِمْ ‏ ‏يَسْعَى بَيْنَ أَيْدِيهِمْ ‏","","",""],[20746,20746,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي مَرْيَمَ الْغَسَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ حَكِيمُ بْنُ عُمَيْرٍ ‏ ‏وحَبِيبُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدَعُ رَجُلٌ مِنْكُمْ أَنْ يَعْمَلَ لِلَّهِ عَزَّ وَجَلَّ أَلْفَ حَسَنَةٍ حِينَ يُصْبِحُ يَقُولُ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ فَإِنَّهُ أَلْفُ حَسَنَةٍ فَإِنَّهُ لَنْ يَعْمَلَ إِنْ شَاءَ اللَّهُ مِثْلَ ذَلِكَ فِي يَوْمٍ مِنْ الذُّنُوبِ وَيَكُونُ مَا عَمِلَ مِنْ خَيْرٍ سِوَى ذَلِكَ وَافِرًا ‏","","",""],[20747,20747,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عُقْبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏كُرَيْبٌ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ أَخْبِرْنِي كَيْفَ صَنَعْتُمْ عَشِيَّةَ ‏ ‏رَدِفْتَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ جِئْنَا ‏ ‏الشِّعْبَ ‏ ‏الَّذِي ‏ ‏يُنِيخُ ‏ ‏فِيهِ النَّاسُ لِلْمَغْرِبِ ‏ ‏فَأَنَاخَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاقَتَهُ ثُمَّ ‏ ‏بَالَ مَاءً ‏ ‏قَالَ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ ‏ ‏ثُمَّ دَعَا بِالْوَضُوءِ فَتَوَضَّأَ وُضُوءًا لَيْسَ بِالْبَالِغِ جِدًّا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ الصَّلَاةَ قَالَ الصَّلَاةُ أَمَامَكَ قَالَ فَرَكِبَ حَتَّى قَدِمَ ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَأَقَامَ الْمَغْرِبَ ثُمَّ ‏ ‏أَنَاخَ ‏ ‏النَّاسُ فِي مَنَازِلِهِمْ وَلَمْ يَحُلُّوا حَتَّى أَقَامَ الْعِشَاءَ فَصَلَّى ثُمَّ حَلَّ النَّاسُ قَالَ فَقُلْتُ كَيْفَ فَعَلْتُمْ حِينَ أَصْبَحْتُمْ قَالَ ‏ ‏رَدِفَهُ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏وَانْطَلَقْتُ أَنَا فِي ‏ ‏سُبَّاقِ ‏ ‏قُرَيْشٍ ‏ ‏عَلَى رِجْلَيَّ ‏","","",""],[20748,20748,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا رِبَا فِيمَا كَانَ يَدًا بِيَدٍ ‏ ‏قَالَ ‏ ‏يَعْنِي إِنَّمَا الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20749,20749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُ بْنُ الْحَكَمِ ‏ ‏عَنْ ‏ ‏مَوْلَى قُدَامَةَ بْنِ مَظْعُونٍ ‏ ‏عَنْ ‏ ‏مَوْلَى أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ انْطَلَقَ مَعَ ‏ ‏أُسَامَةَ ‏ ‏إِلَى ‏ ‏وَادِي الْقُرَى ‏ ‏يَطْلُبُ مَالًا لَهُ وَكَانَ يَصُومُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ فَقَالَ لَهُ ‏ ‏مَوْلَاهُ ‏ ‏لِمَ تَصُومُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ وَأَنْتَ شَيْخٌ كَبِيرٌ قَدْ رَقَقْتَ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَصُومُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ فَسُئِلَ عَنْ ذَلِكَ فَقَالَ ‏ ‏إِنَّ أَعْمَالَ النَّاسِ تُعْرَضُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ ‏","","",""],[20750,20750,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏أَبِي ظِبْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْحُرَقَةِ ‏ ‏مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏قَالَ فَصَبَّحْنَاهُمْ فَقَاتَلْنَاهُمْ فَكَانَ مِنْهُمْ رَجُلٌ إِذَا أَقْبَلَ الْقَوْمُ كَانَ مِنْ أَشَدِّهِمْ عَلَيْنَا وَإِذَا ‏ ‏أَدْبَرُوا ‏ ‏كَانَ حَامِيَتَهُمْ قَالَ ‏ ‏فَغَشِيتُهُ ‏ ‏أَنَا وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ فَلَمَّا ‏ ‏غَشِينَاهُ ‏ ‏قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَكَفَّ عَنْهُ الْأَنْصَارِيُّ وَقَتَلْتُهُ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏أُسَامَةُ ‏ ‏أَقَتَلْتَهُ بَعْدَمَا قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا كَانَ ‏ ‏مُتَعَوِّذًا ‏ ‏مِنْ الْقَتْلِ فَكَرَّرَهَا عَلَيَّ حَتَّى تَمَنَّيْتُ أَنِّي لَمْ أَكُنْ أَسْلَمْتُ إِلَّا يَوْمَئِذٍ ‏","","",""],[20751,20751,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَرَكْتُ بَعْدِي فِتْنَةً أَضَرَّ عَلَى أُمَّتِي مِنْ النِّسَاءِ عَلَى الرِّجَالِ ‏","","",""],[20752,20752,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ وَلَا الْكَافِرُ الْمُسْلِمَ ‏","","",""],[20753,20753,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْرَفَ عَلَى ‏ ‏أُطُمٍ ‏ ‏مِنْ ‏ ‏آطَامِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ هَلْ تَرَوْنَ مَا أَرَى ‏ ‏إِنِّي لَأَرَى مَوَاقِعَ ‏ ‏الْفِتَنِ ‏ ‏خِلَالَ بُيُوتِكُمْ كَمَوَاقِعِ ‏ ‏الْقَطْرِ ‏","","",""],[20754,20754,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْدَفَهُ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏فَلَمَّا أَتَى ‏ ‏الشِّعْبَ ‏ ‏نَزَلَ ‏ ‏فَبَالَ ‏ ‏وَلَمْ يَقُلْ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ ‏ ‏فَصَبَبْتُ عَلَيْهِ فَتَوَضَّأَ وُضُوءًا خَفِيفًا فَقُلْتُ الصَّلَاةَ فَقَالَ الصَّلَاةُ أَمَامَكَ قَالَ ثُمَّ أَتَى ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَصَلَّى الْمَغْرِبَ ثُمَّ حَلُّوا ‏ ‏رِحَالَهُمْ ‏ ‏وَأَعَنْتُهُ ثُمَّ صَلَّى الْعِشَاءَ ‏","","",""],[20755,20755,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرٌو يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏يَقُولُ الذَّهَبُ بِالذَّهَبِ وَزْنًا بِوَزْنٍ قَالَ فَلَقِيتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقُلْتُ أَرَأَيْتَ مَا تَقُولُ أَشَيْئًا وَجَدْتَهُ فِي كِتَابِ اللَّهِ أَوْ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَيْسَ بِشَيْءٍ وَجَدْتُهُ فِي كِتَابِ اللَّهِ أَوْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20756,20756,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ يَسْأَلُ ‏ ‏سَعْدًا ‏ ‏عَنْ الطَّاعُونِ فَقَالَ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَا أُحَدِّثُكَ عَنْهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذَا عَذَابٌ أَوْ كَذَا أَرْسَلَهُ اللَّهُ عَلَى نَاسٍ قَبْلَكُمْ ‏ ‏أَوْ طَائِفَةٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَهُوَ يَجِيءُ أَحْيَانًا وَيَذْهَبُ أَحْيَانًا فَإِذَا وَقَعَ بِأَرْضٍ فَلَا تَدْخُلُوا عَلَيْهِ وَإِذَا وَقَعَ بِأَرْضٍ فَلَا تَخْرُجُوا فِرَارًا مِنْهُ ‏","","",""],[20757,20757,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ أَيْنَ تَنْزِلُ غَدًا إِنْ شَاءَ اللَّهُ وَذَلِكَ زَمَنَ الْفَتْحِ فَقَالَ هَلْ تَرَكَ لَنَا ‏ ‏عَقِيلٌ ‏ ‏مِنْ مَنْزِلٍ ثُمَّ قَالَ ‏ ‏لَا يَرِثُ الْكَافِرُ الْمُؤْمِنَ وَلَا الْمُؤْمِنُ الْكَافِرَ ‏","","",""],[20758,20758,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ قَيْسٍ أَبُو غُصْنٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ الْأَيَّامَ ‏ ‏يَسْرُدُ ‏ ‏حَتَّى يُقَالَ لَا يُفْطِرُ وَيُفْطِرُ الْأَيَّامَ حَتَّى لَا يَكَادَ أَنْ يَصُومَ إِلَّا يَوْمَيْنِ مِنْ الْجُمُعَةِ إِنْ كَانَا فِي صِيَامِهِ وَإِلَّا صَامَهُمَا وَلَمْ يَكُنْ يَصُومُ مِنْ شَهْرٍ مِنْ الشُّهُورِ مَا يَصُومُ مِنْ شَعْبَانَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ تَصُومُ لَا تَكَادُ أَنْ تُفْطِرَ وَتُفْطِرَ حَتَّى لَا تَكَادَ أَنْ تَصُومَ إِلَّا يَوْمَيْنِ إِنْ دَخَلَا فِي صِيَامِكَ وَإِلَّا صُمْتَهُمَا قَالَ أَيُّ يَوْمَيْنِ قَالَ قُلْتُ يَوْمُ ‏ ‏الِاثْنَيْنِ وَيَوْمُ الْخَمِيسِ قَالَ ‏ ‏ذَانِكَ يَوْمَانِ تُعْرَضُ فِيهِمَا الْأَعْمَالُ عَلَى رَبِّ الْعَالَمِينَ وَأُحِبُّ أَنْ يُعْرَضَ عَمَلِي وَأَنَا صَائِمٌ قَالَ قُلْتُ وَلَمْ أَرَكَ تَصُومُ مِنْ شَهْرٍ مِنْ الشُّهُورِ مَا تَصُومُ مِنْ شَعْبَانَ قَالَ ذَاكَ شَهْرٌ يَغْفُلُ النَّاسُ عَنْهُ بَيْنَ رَجَبٍ وَرَمَضَانَ وَهُوَ شَهْرٌ يُرْفَعُ فِيهِ الْأَعْمَالُ إِلَى رَبِّ الْعَالَمِينَ فَأُحِبُّ أَنْ يُرْفَعَ عَمَلِي وَأَنَا صَائِمٌ ‏","","",""],[20759,20759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَطَاءٍ ‏ ‏أَسَمِعْتَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَذَكَرَ قِصَّةً وَلَكِنِّي ‏ ‏سَمِعْتُهُ يَقُولُ أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا دَخَلَ الْبَيْتَ دَعَا فِي نَوَاحِيهِ كُلِّهَا وَلَمْ يُصَلِّ فِيهِ حَتَّى خَرَجَ فَلَمَّا خَرَجَ ‏ ‏رَكَعَ رَكْعَتَيْنِ فِي قِبَلِ ‏ ‏الْكَعْبَةِ ‏ ‏وَقَالَ هَذِهِ الْقِبْلَةُ ‏","","",""],[20760,20760,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏ثَقُلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَبَطْتُ وَهَبَطَ النَّاسُ مَعِي إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَدَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ أَصْمَتَ فَلَا يَتَكَلَّمُ فَجَعَلَ ‏ ‏يَرْفَعُ يَدَيْهِ إِلَى السَّمَاءِ ثُمَّ يَصُبُّهَا عَلَيَّ أَعْرِفُ أَنَّهُ يَدْعُو لِي ‏","","",""],[20761,20761,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏وَرَدِيفُهُ ‏ ‏أُسَامَةُ ‏ ‏فَجَعَلَ ‏ ‏يَكْبَحُ ‏ ‏رَاحِلَتَهُ حَتَّى أَنَّ ‏ ‏ذِفْرَيْهَا ‏ ‏لَتَكَادُ أَنْ تَمَسَّ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَنْ تُصِيبَ ‏ ‏قَادِمَةَ الرَّحْلِ وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏عَلَيْكُمْ بِالسَّكِينَةِ ‏ ‏وَالْوَقَارِ ‏ ‏فَإِنَّ ‏ ‏الْبِرَّ ‏ ‏لَيْسَ فِي ‏ ‏إِيضَاعِ ‏ ‏الْإِبِلِ ‏","","",""],[20762,20762,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏ثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا رِبَا فِيمَا كَانَ يَدًا بِيَدٍ ‏","","",""],[20763,20763,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أُبَيٍّ ‏ ‏فِي مَرَضِهِ ‏ ‏نَعُودُهُ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كُنْتُ أَنْهَاكَ عَنْ حُبِّ ‏ ‏يَهُودَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقَدْ أَبْغَضَهُمْ ‏ ‏أَسْعَدُ بْنُ زُرَارَةَ ‏ ‏فَمَاتَ ‏","","",""],[20764,20764,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْبَيْتِ ‏","","",""],[20765,20765,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏قَالَ فَلَمَّا وَقَعَتْ الشَّمْسُ دَفْعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا سَمِعَ ‏ ‏حَطْمَةَ ‏ ‏النَّاسِ خَلْفَهُ قَالَ رُوَيْدًا أَيُّهَا النَّاسُ ‏ ‏عَلَيْكُمْ السَّكِينَةَ فَإِنَّ ‏ ‏الْبِرَّ ‏ ‏لَيْسَ ‏ ‏بِالْإِيضَاعِ ‏ ‏قَالَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏الْتَحَمَ ‏ ‏عَلَيْهِ النَّاسُ ‏ ‏أَعْنَقَ ‏ ‏وَإِذَا وَجَدَ ‏ ‏فُرْجَةً ‏ ‏نَصَّ ‏ ‏حَتَّى مَرَّ ‏ ‏بِالشِّعْبِ ‏ ‏الَّذِي يَزْعُمُ كَثِيرٌ مِنْ النَّاسِ أَنَّهُ صَلَّى فِيهِ فَنَزَلَ بِهِ فَبَالَ ‏ ‏مَا يَقُولُ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ كَمَا يَقُولُونَ ‏ ‏ثُمَّ جِئْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏فَتَوَضَّأَ ثُمَّ قَالَ قُلْتُ الصَّلَاةَ يَا رَسُولَ اللَّهِ قَالَ فَقَالَ الصَّلَاةُ أَمَامَكَ قَالَ فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا صَلَّى حَتَّى أَتَى ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَنَزَلَ بِهَا فَجَمَعَ بَيْنَ الصَّلَاتَيْنِ الْمَغْرِبِ وَالْعِشَاءِ الْآخِرَةِ ‏","","",""],[20766,20766,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رِدْفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏فَلَمَّا وَقَعَتْ الشَّمْسُ دَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا سَمِعَ ‏ ‏حَطْمَةَ ‏ ‏النَّاسِ خَلْفَهُ قَالَ رُوَيْدًا أَيُّهَا النَّاسُ ‏ ‏عَلَيْكُمْ السَّكِينَةَ فَإِنَّ ‏ ‏الْبِرَّ ‏ ‏لَيْسَ ‏ ‏بِالْإِيضَاعِ ‏ ‏قَالَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏الْتَحَمَ ‏ ‏عَلَيْهِ النَّاسُ ‏ ‏أَعْنَقَ ‏ ‏وَإِذَا وَجَدَ ‏ ‏فُرْجَةً ‏ ‏نَصَّ ‏ ‏حَتَّى مَرَّ ‏ ‏بِالشِّعْبِ ‏ ‏الَّذِي يَزْعُمُ كَثِيرٌ مِنْ النَّاسِ أَنَّهُ صَلَّى فِيهِ فَنَزَلَ بِهِ فَبَالَ ‏ ‏مَا يَقُولُ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ كَمَا يَقُولُونَ ‏ ‏ثُمَّ جِئْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏فَتَوَضَّأَ ثُمَّ قَالَ قُلْتُ الصَّلَاةَ يَا رَسُولَ اللَّهِ قَالَ فَقَالَ الصَّلَاةُ أَمَامَكَ قَالَ فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا صَلَّى حَتَّى أَتَى ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَنَزَلَ بِهَا فَجَمَعَ بَيْنَ الصَّلَاتَيْنِ الْمَغْرِبِ وَالْعِشَاءِ الْآخِرَةِ ‏","","",""],[20767,20767,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَلِيِّ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا رِبًا إِلَّا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20768,20768,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏وَأَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏مَاذَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الطَّاعُونِ فَقَالَ ‏ ‏أُسَامَةُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رِجْزٌ ‏ ‏أُرْسِلَ عَلَى طَائِفَةٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏أَوْ عَلَى طَائِفَةٍ مِمَّنْ كَانَ قَبْلَكُمْ الشَّكُّ فِي الْحَدِيثِ ‏ ‏فَإِذَا سَمِعْتُمْ بِهِ بِأَرْضٍ فَلَا تَقْدَمُوا عَلَيْهِ وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏فِي حَدِيثِهِ لَا يُخْرِجُكُمْ إِلَّا فِرَارًا مِنْهُ ‏","","",""],[20769,20769,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمٍ ‏ ‏مَوْلًى ‏ ‏لِبَنِي لَيْثٍ ‏ ‏وَكَانَ قَدِيمًا ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏مَرْوَانُ بْنُ الْحَكَمِ ‏ ‏عَلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَحَكَاهُ ‏ ‏مَرْوَانُ ‏ ‏قَالَ ‏ ‏أَبُو مَعْشَرٍ ‏ ‏وَقَدْ لَقِيَهُمَا جَمِيعًا ‏ ‏فَقَالَ ‏ ‏أُسَامَةُ ‏ ‏يَا ‏ ‏مَرْوَانُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ ‏ ‏فَاحِشٍ ‏ ‏مُتَفَحِّشٍ ‏","","",""],[20770,20770,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ الْمُنْكَدِرِ ‏ ‏حَدَّثَهُ أَنَّهُ أَخْبَرَهُ أَنَّهُ حَدَّثَهُ ‏ ‏مَنْ سَمِعَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏يَقُولُ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِالْمُزْدَلِفَةِ ‏","","",""],[20771,20771,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيْنَ نَنْزِلُ غَدًا فِي حَجَّتِهِ قَالَ وَهَلْ تَرَكَ لَنَا ‏ ‏عَقِيلٌ ‏ ‏مَنْزِلًا ثُمَّ قَالَ نَحْنُ نَازِلُونَ غَدًا إِنْ شَاءَ اللَّهُ ‏ ‏بِخَيْفِ ‏ ‏بَنِي كِنَانَةَ ‏ ‏يَعْنِي ‏ ‏الْمُحَصَّبَ ‏ ‏حَيْثُ قَاسَمَتْ ‏ ‏قُرَيْشٌ ‏ ‏عَلَى الْكُفْرِ وَذَلِكَ أَنَّ ‏ ‏بَنِي كِنَانَةَ ‏ ‏حَالَفَتْ ‏ ‏قُرَيْشًا ‏ ‏عَلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏أَنْ لَا ‏ ‏يُنَاكِحُوهُمْ وَلَا يُبَايِعُوهُمْ وَلَا ‏ ‏يُؤْوُهُمْ ‏ ‏ثُمَّ قَالَ عِنْدَ ذَلِكَ ‏ ‏لَا يَرِثُ الْكَافِرُ الْمُسْلِمَ وَلَا الْمُسْلِمُ الْكَافِرَ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَالْخَيْفُ الْوَادِي ‏","","",""],[20772,20772,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكِبَ حِمَارًا عَلَيْهِ ‏ ‏إِكَافٌ ‏ ‏تَحْتَهُ قَطِيفَةٌ ‏ ‏فَدَكِيَّةٌ ‏ ‏وَأَرْدَفَ ‏ ‏وَرَاءَهُ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏وَهُوَ ‏ ‏يَعُودُ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏فِي ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏وَذَلِكَ قَبْلَ وَقْعَةِ ‏ ‏بَدْرٍ ‏ ‏حَتَّى مَرَّ بِمَجْلِسٍ فِيهِ أَخْلَاطٌ مِنْ الْمُسْلِمِينَ وَالْمُشْرِكِينَ عَبَدَةِ الْأَوْثَانِ ‏ ‏وَالْيَهُودِ ‏ ‏فِيهِمْ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏وَفِي الْمَجْلِسِ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَلَمَّا ‏ ‏غَشِيَتْ ‏ ‏الْمَجْلِسَ ‏ ‏عَجَاجَةُ ‏ ‏الدَّابَّةِ ‏ ‏خَمَّرَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏أَنْفَهُ بِرِدَائِهِ ثُمَّ قَالَ لَا تُغَبِّرُوا عَلَيْنَا فَسَلَّمَ عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ وَقَفَ فَنَزَلَ ‏ ‏فَدَعَاهُمْ إِلَى اللَّهِ وَقَرَأَ عَلَيْهِمْ الْقُرْآنَ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏أَيُّهَا الْمَرْءُ لَا أَحْسَنَ مِنْ هَذَا إِنْ كَانَ مَا تَقُولُ حَقًّا فَلَا ‏ ‏تُؤْذِينَا فِي مَجَالِسِنَا وَارْجِعْ إِلَى ‏ ‏رَحْلِكَ ‏ ‏فَمَنْ جَاءَكَ مِنَّا فَاقْصُصْ عَلَيْهِ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏اغْشَنَا ‏ ‏فِي مَجَالِسِنَا فَإِنَّا نُحِبُّ ذَلِكَ قَالَ ‏ ‏فَاسْتَبَّ ‏ ‏الْمُسْلِمُونَ وَالْمُشْرِكُونَ ‏ ‏وَالْيَهُودُ ‏ ‏حَتَّى هَمُّوا أَنْ ‏ ‏يَتَوَاثَبُوا ‏ ‏فَلَمْ يَزَلْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَفِّضُهُمْ ‏ ‏ثُمَّ رَكِبَ دَابَّتَهُ حَتَّى دَخَلَ عَلَى ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏فَقَالَ أَيْ ‏ ‏سَعْدُ ‏ ‏أَلَمْ تَسْمَعْ مَا قَالَ ‏ ‏أَبُو حُبَابٍ يُرِيدُ عَبْدَ اللَّهِ بْنَ أُبَيٍّ ‏ ‏قَالَ كَذَا وَكَذَا فَقَالَ اعْفُ عَنْهُ يَا رَسُولَ اللَّهِ وَاصْفَحْ فَوَاللَّهِ لَقَدْ أَعْطَاكَ اللَّهُ الَّذِي أَعْطَاكَ وَلَقَدْ اصْطَلَحَ أَهْلُ هَذِهِ الْبُحَيْرَةِ أَنْ يُتَوِّجُوهُ فَيُعَصِّبُونَهُ بِالْعِصَابَةِ فَلَمَّا رَدَّ اللَّهُ ذَلِكَ بِالْحَقِّ الَّذِي أَعْطَاكَهُ شَرِقَ بِذَلِكَ فَذَاكَ فَعَلَ بِهِ مَا رَأَيْتَ فَعَفَا عَنْهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَهُ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ وَلَقَدْ اجْتَمَعَ أَهْلُ هَذِهِ الْبُحَيْرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكِبَ حِمَارًا عَلَى ‏ ‏إِكَافٍ ‏ ‏عَلَيْهِ قَطِيفَةٌ ‏ ‏فَدَكِيَّةٌ ‏ ‏وَأَرْدَفَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏وَرَاءَهُ يَعُودُ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏فِي ‏ ‏بَنِي الْخَزْرَجِ ‏ ‏قَبْلَ وَقْعَةِ ‏ ‏بَدْرٍ ‏ ‏فَذَكَرَهُ وَقَالَ الْبَحْرَةِ ‏","","",""],[20773,20773,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏أَبَا النَّضْرِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَ وَالِدَهُ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏قَالَ فَقَالَ لَهُ إِنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنِّي أَعْزِلُ عَنْ امْرَأَتِي قَالَ لِمَ قَالَ شَفَقًا عَلَى وَلَدِهَا ‏ ‏أَوْ عَلَى أَوْلَادِهَا ‏ ‏فَقَالَ إِنْ كَانَ كَذَلِكَ فَلَا مَا ضَارَّ ذَلِكَ ‏ ‏فَارِسَ ‏ ‏وَلَا ‏ ‏الرُّومَ ‏","","",""],[20774,20774,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْهَيْثَمِ بْنِ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏لَمَّا نَزَلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَّمَهُ الْوُضُوءَ فَلَمَّا فَرَغَ مِنْ وُضُوئِهِ أَخَذَ حَفْنَةً مِنْ مَاءٍ فَرَشَّ بِهَا نَحْوَ الْفَرْجِ قَالَ فَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرُشُّ بَعْدَ وُضُوئِهِ ‏","","",""],[20775,20775,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏الْكَآبَةُ ‏ ‏فَسَأَلْتُهُ مَا لَهُ فَقَالَ لَمْ يَأْتِنِي ‏ ‏جِبْرِيلُ ‏ ‏مُنْذُ ثَلَاثٍ قَالَ فَإِذَا ‏ ‏جِرْوُ ‏ ‏كَلْبٍ بَيْنَ بُيُوتِهِ ‏ ‏فَأَمَرَ بِهِ فَقُتِلَ فَبَدَا لَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَبَهَشَ ‏ ‏إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ رَآهُ فَقَالَ لَمْ تَأْتِنِي فَقَالَ إِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا تَصَاوِيرُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏كَآبَةٌ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏عُثْمَانَ بْنِ عُمَرَ ‏ ‏إِلَّا أَنَّهُ قَالَ فَلَمْ يَأْتِنِي مُنْذُ ثَلَاثٍ ‏","","",""],[20776,20776,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏جَامِعُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏كُلْثُومٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْخِلْ عَلَيَّ أَصْحَابِي فَدَخَلُوا عَلَيْهِ فَكَشَفَ الْقِنَاعَ ثُمَّ قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏جَامِعٍ ‏ ‏إِلَّا أَنَّهُ قَالَ فَدَخَلُوا عَلَيْهِ وَهُوَ ‏ ‏مُتَقَنِّعٌ ‏ ‏بِبُرْدٍ ‏ ‏لَهُ ‏ ‏مَعَافِرِيٍّ وَلَمْ يَقُلْ ‏ ‏وَالنَّصَارَى ‏","","",""],[20777,20777,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْضُ بَنَاتِهِ ‏ ‏أَنَّ صَبِيًّا لَهَا ‏ ‏ابْنًا ‏ ‏أَوْ ابْنَةً ‏ ‏قَدْ ‏ ‏احْتُضِرَتْ ‏ ‏فَاشْهَدْنَا قَالَ فَأَرْسَلَ إِلَيْهَا يَقْرَأُ السَّلَامَ وَيَقُولُ ‏ ‏إِنَّ لِلَّهِ مَا أَخَذَ وَمَا أَعْطَى وَكُلُّ شَيْءٍ عِنْدَهُ إِلَى أَجَلٍ مُسَمًّى فَلْتَصْبِرْ وَلْتَحْتَسِبْ فَأَرْسَلَتْ تُقْسِمُ عَلَيْهِ فَقَامَ وَقُمْنَا فَرُفِعَ الصَّبِيُّ إِلَى حِجْرِ ‏ ‏أَوْ فِي حِجْرِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَفْسُهُ ‏ ‏تَقَعْقَعُ ‏ ‏وَفِي الْقَوْمِ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏وَأُبَيٌّ ‏ ‏أَحْسِبُ ‏ ‏فَفَاضَتْ عَيْنَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏مَا هَذَا يَا رَسُولَ اللَّهِ قَالَ هَذِهِ رَحْمَةٌ يَضَعُهَا اللَّهُ فِي قُلُوبِ مَنْ يَشَاءُ مِنْ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""],[20778,20778,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اجْتَمَعَ ‏ ‏جَعْفَرٌ ‏ ‏وَعَلِيٌّ ‏ ‏وَزَيْدُ بْنُ حَارِثَةَ ‏ ‏فَقَالَ ‏ ‏جَعْفَرٌ ‏ ‏أَنَا أَحَبُّكُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏أَنَا أَحَبُّكُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏زَيْدٌ ‏ ‏أَنَا أَحَبُّكُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا انْطَلِقُوا بِنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى نَسْأَلَهُ فَقَالَ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَجَاءُوا يَسْتَأْذِنُونَهُ فَقَالَ اخْرُجْ فَانْظُرْ مَنْ هَؤُلَاءِ فَقُلْتُ هَذَا ‏ ‏جَعْفَرٌ ‏ ‏وَعَلِيٌّ ‏ ‏وَزَيْدٌ ‏ ‏مَا أَقُولُ أَبِي قَالَ ائْذَنْ لَهُمْ وَدَخَلُوا فَقَالُوا مَنْ أَحَبُّ إِلَيْكَ قَالَ ‏ ‏فَاطِمَةُ ‏ ‏قَالُوا نَسْأَلُكَ عَنْ الرِّجَالِ قَالَ ‏ ‏أَمَّا أَنْتَ يَا ‏ ‏جَعْفَرُ ‏ ‏فَأَشْبَهَ خَلْقُكَ خَلْقِي وَأَشْبَهَ خُلُقِي خُلُقُكَ وَأَنْتَ مِنِّي وَشَجَرَتِي وَأَمَّا أَنْتَ يَا ‏ ‏عَلِيُّ ‏ ‏فَخَتَنِي ‏ ‏وَأَبُو وَلَدِي وَأَنَا مِنْكَ وَأَنْتَ مِنِّي وَأَمَّا أَنْتَ يَا ‏ ‏زَيْدُ ‏ ‏فَمَوْلَايَ ‏ ‏وَمِنِّي وَإِلَيَّ وَأَحَبُّ الْقَوْمِ إِلَيَّ ‏","","",""],[20779,20779,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنِي ‏ ‏أُسَامَةُ ‏ ‏أَنَّهُ قَالَ ‏ ‏الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20780,20780,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُمَيْمَةَ ابْنَةِ زَيْنَبَ ‏ ‏وَنَفْسُهَا ‏ ‏تَقَعْقَعُ ‏ ‏كَأَنَّهَا فِي ‏ ‏شَنٍّ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ مَا أَخَذَ وَلِلَّهِ مَا أَعْطَى وَكُلٌّ إِلَى أَجَلٍ مُسَمًّى فَدَمَعَتْ عَيْنَاهُ فَقَالَ لَهُ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَتَبْكِي أَوَلَمْ تَنْهَ عَنْ الْبُكَاءِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هِيَ رَحْمَةٌ جَعَلَهَا اللَّهُ فِي قُلُوبِ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""],[20781,20781,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏قَالَ ‏ ‏خَرَجْتُ حَاجًّا فَدَخَلْتُ ‏ ‏الْبَيْتَ ‏ ‏فَلَمَّا كُنْتُ عِنْدَ السَّارِيَتَيْنِ مَضَيْتُ حَتَّى لَزِقْتُ بِالْحَائِطِ قَالَ وَجَاءَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَتَّى قَامَ إِلَى جَنْبِي فَصَلَّى أَرْبَعًا قَالَ فَلَمَّا صَلَّى قُلْتُ لَهُ أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْبَيْتِ ‏ ‏قَالَ فَقَالَ هَاهُنَا أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏صَلَّى قَالَ قُلْتُ فَكَمْ صَلَّى قَالَ عَلَى هَذَا أَجِدُنِي أَلُومُ نَفْسِي أَنِّي مَكَثْتُ مَعَهُ عُمُرًا ثُمَّ لَمْ أَسْأَلْهُ كَمْ صَلَّى فَلَمَّا كَانَ الْعَامُ الْمُقْبِلُ قَالَ خَرَجْتُ حَاجًّا قَالَ فَجِئْتُ حَتَّى قُمْتُ فِي مَقَامِهِ قَالَ فَجَاءَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏حَتَّى قَامَ إِلَى جَنْبِي فَلَمْ يَزَلْ يُزَاحِمُنِي حَتَّى أَخْرَجَنِي مِنْهُ ثُمَّ صَلَّى فِيهِ أَرْبَعًا ‏","","",""],[20782,20782,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي الدَّسْتُوَائِيَّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏أَنَّ ‏ ‏مَوْلَى قُدَامَةَ بْنِ مَظْعُونٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏مَوْلَى أُسَامَةَ بْنِ زَيْدٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏كَانَ يَخْرُجُ فِي مَالٍ لَهُ ‏ ‏بِوَادِي الْقُرَى ‏ ‏فَيَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ فَقُلْتُ لَهُ لِمَ تَصُومُ فِي السَّفَرِ وَقَدْ كَبِرْتَ وَرَقَقْتَ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ فَقُلْتُ يَا رَسُولَ اللَّهِ لِمَ تَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ قَالَ إِنَّ الْأَعْمَالَ تُعْرَضُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ ‏","","",""],[20783,20783,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُمْتُ عَلَى بَابِ الْجَنَّةِ فَإِذَا عَامَّةُ مَنْ دَخَلَهَا الْمَسَاكِينُ وَإِذَا أَصْحَابُ الْجَدِّ ‏ ‏وَقَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَغَيْرُهُ إِلَّا أَصْحَابَ الْجَدِّ ‏ ‏مَحْبُوسُونَ إِلَّا أَصْحَابَ النَّارِ فَقَدْ أُمِرَ بِهِمْ إِلَى النَّارِ وَقُمْتُ عَلَى بَابِ النَّارِ فَإِذَا عَامَّةُ مَنْ يَدْخُلُهَا النِّسَاءُ ‏","","",""],[20784,20784,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أُسَامَةُ ‏ ‏عَنْ سَيْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ وَأَنَا شَاهِدٌ قَالَ كَانَ ‏ ‏سَيْرُهُ ‏ ‏الْعَنَقَ ‏ ‏فَإِذَا وَجَدَ ‏ ‏فَجْوَةً ‏ ‏نَصَّ ‏ ‏وَالنَّصُّ ‏ ‏فَوْقَ ‏ ‏الْعَنَقِ ‏ ‏وَأَنَا ‏ ‏رَدِيفُهُ ‏","","",""],[20785,20785,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِأُسَامَةَ ‏ ‏أَلَا تُكَلِّمُ ‏ ‏عُثْمَانَ ‏ ‏فَقَالَ إِنَّكُمْ تَرَوْنَ أَنْ لَا أُكَلِّمَهُ إِلَّا سَمْعَكُمْ إِنِّي لَا أُكَلِّمُهُ فِيمَا بَيْنِي وَبَيْنَهُ مَا دُونَ أَنْ أَفْتَتِحَ أَمْرًا لَا أُحِبُّ أَنْ أَكُونَ أَوَّلَ مَنْ افْتَتَحَهُ وَاللَّهِ لَا أَقُولُ لِرَجُلٍ إِنَّكَ خَيْرُ النَّاسِ وَإِنْ كَانَ عَلَيَّ أَمِيرًا بَعْدَ إِذْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالُوا وَمَا سَمِعْتَهُ يَقُولُ قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏يُجَاءُ بِالرَّجُلِ يَوْمَ الْقِيَامَةِ ‏ ‏فَيُلْقَى فِي النَّارِ ‏ ‏فَتَنْدَلِقُ ‏ ‏بِهِ ‏ ‏أَقْتَابُهُ ‏ ‏فَيَدُورُ بِهَا فِي النَّارِ كَمَا يَدُورُ الْحِمَارُ ‏ ‏بِرَحَاهُ ‏ ‏فَيُطِيفُ بِهِ أَهْلُ النَّارِ فَيَقُولُونَ يَا فُلَانُ مَا لَكَ مَا أَصَابَكَ أَلَمْ تَكُنْ تَأْمُرُنَا بِالْمَعْرُوفِ ‏ ‏وَتَنْهَانَا عَنْ الْمُنْكَرِ فَقَالَ كُنْتُ آمُرُكُمْ بِالْمَعْرُوفِ وَلَا آتِيهِ وَأَنْهَاكُمْ عَنْ الْمُنْكَرِ وَآتِيهِ ‏","","",""],[20786,20786,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى قَرْيَةٍ يُقَالُ لَهَا ‏ ‏أُبْنَى ‏ ‏فَقَالَ ائْتِهَا صَبَاحًا ثُمَّ حَرِّقْ ‏","","",""],[20787,20787,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏ابْنِ أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أُسَامَةَ ‏ ‏قَالَ ‏ ‏كَسَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُبْطِيَّةً ‏ ‏كَثِيفَةً كَانَتْ مِمَّا أَهْدَاهَا ‏ ‏دِحْيَةُ الْكَلْبِيُّ ‏ ‏فَكَسَوْتُهَا امْرَأَتِي فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكَ لَمْ تَلْبَسْ ‏ ‏الْقُبْطِيَّةَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَسَوْتُهَا امْرَأَتِي فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْهَا فَلْتَجْعَلْ تَحْتَهَا غِلَالَةً إِنِّي أَخَافُ أَنْ تَصِفَ حَجْمَ عِظَامِهَا ‏","","",""],[20788,20788,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا تَمِيمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏يُحَدِّثُهُ ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْخُذُنِي ‏ ‏فَيُقْعِدُنِي عَلَى فَخِذِهِ وَيُقْعِدُ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏عَلَى فَخِذِهِ الْأُخْرَى ثُمَّ يَضُمُّنَا ثُمَّ يَقُولُ اللَّهُمَّ ارْحَمْهُمَا فَإِنِّي أَرْحَمُهُمَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ الْمَدِينِيِّ ‏ ‏هُوَ ‏ ‏السَّلِّيُّ ‏ ‏مِنْ ‏ ‏عَنَزَةَ ‏ ‏إِلَى ‏ ‏رَبِيعَةَ يَعْنِي أَبَا تَمِيمَةَ السَّلِّيَّ ‏","","",""],[20789,20789,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَسَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُبْطِيَّةً ‏ ‏كَثِيفَةً مِمَّا أَهْدَاهَا لَهُ ‏ ‏دِحْيَةُ الْكَلْبِيُّ ‏ ‏فَكَسَوْتُهَا امْرَأَتِي فَقَالَ ‏ ‏مَا لَكَ لَمْ تَلْبَسْ ‏ ‏الْقُبْطِيَّةَ ‏ ‏قُلْتُ كَسَوْتُهَا امْرَأَتِي فَقَالَ مُرْهَا فَلْتَجْعَلْ تَحْتَهَا ‏ ‏غِلَالَةً ‏ ‏فَإِنِّي أَخَافُ أَنْ تَصِفَ حَجْمَ عِظَامِهَا ‏","","",""],[20790,20790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَتْ ‏ ‏ابْنَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏ابْنِي ‏ ‏يُقْبَضُ ‏ ‏فَأْتِنَا فَأَرْسَلَ بِإِقْرَاءِ السَّلَامِ ‏ ‏وَيَقُولُ ‏ ‏لِلَّهِ مَا أَخَذَ وَلِلَّهِ مَا أَعْطَى وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى قَالَ فَأَرْسَلَتْ إِلَيْهِ تُقْسِمُ عَلَيْهِ لَيَأْتِيَنَّ قَالَ فَقَامَ وَقُمْنَا مَعَهُ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏وَأُبَيُّ بْنُ كَعْبٍ ‏ ‏وَسَعْدُ بْنُ عُبَادَةَ ‏ ‏قَالَ فَأَخَذَ الصَّبِيَّ وَنَفْسُهُ ‏ ‏تَقَعْقَعُ ‏ ‏قَالَ فَدَمَعَتْ عَيْنَاهُ فَقَالَ ‏ ‏سَعْدٌ ‏ ‏يَا رَسُولَ اللَّهِ مَا هَذَا قَالَ هَذِهِ رَحْمَةٌ جَعَلَهَا اللَّهُ فِي قُلُوبِ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""],[20791,20791,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي فُدَيْكٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏أَرْدَفَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏حَتَّى دَخَلَ ‏ ‏الشِّعْبَ ‏ ‏ثُمَّ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ وَتَوَضَّأَ ثُمَّ رَكِبَ وَلَمْ يُصَلِّ ‏","","",""],[20792,20792,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ ‏","","",""],[20793,20793,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزِّبْرِقَانِ ‏ ‏أَنَّ ‏ ‏رَهْطًا ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏مَرَّ بِهِمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَهُمْ مُجْتَمِعُونَ فَأَرْسَلُوا إِلَيْهِ غُلَامَيْنِ لَهُمْ يَسْأَلَانِهِ عَنْ الصَّلَاةِ الْوُسْطَى فَقَالَ هِيَ الْعَصْرُ فَقَامَ إِلَيْهِ رَجُلَانِ مِنْهُمْ فَسَأَلَاهُ فَقَالَ هِيَ الظُّهْرُ ‏ ‏ثُمَّ انْصَرَفَا إِلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏فَسَأَلَاهُ فَقَالَ هِيَ الظُّهْرُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الظُّهْرَ ‏ ‏بِالْهَجِيرِ ‏ ‏وَلَا يَكُونُ وَرَاءَهُ إِلَّا الصَّفُّ وَالصَّفَّانِ مِنْ النَّاسِ فِي ‏ ‏قَائِلَتِهِمْ ‏ ‏وَفِي تِجَارَتِهِمْ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى وَقُومُوا لِلَّهِ ‏ ‏قَانِتِينَ ‏ } ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَنْتَهِيَنَّ رِجَالٌ أَوْ لَأُحَرِّقَنَّ بُيُوتَهُمْ ‏","","",""],[20794,20794,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّهُ حَدَّثَهُ قَالَ ‏ ‏كُنْتُ ‏ ‏رِدْفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏فَلَمْ تَرْفَعْ رَاحِلَتُهُ رِجْلَهَا عَادِيَةً حَتَّى بَلَغَ ‏ ‏جَمْعًا ‏","","",""],[20795,20795,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قِيلَ ‏ ‏لِأُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُؤْتَى بِالرَّجُلِ الَّذِي كَانَ يُطَاعُ فِي مَعَاصِي اللَّهِ تَعَالَى فَيُقْذَفُ فِي النَّارِ ‏ ‏فَتَنْدَلِقُ ‏ ‏بِهِ ‏ ‏أَقْتَابُهُ ‏ ‏فَيَسْتَدِيرُ فِيهَا كَمَا يَسْتَدِيرُ الْحِمَارُ فِي الرَّحَا فَيَأْتِي عَلَيْهِ أَهْلُ طَاعَتِهِ مِنْ النَّاسِ فَيَقُولُونَ أَيْ ‏ ‏فُلَ أَيْنَ مَا كُنْتَ تَأْمُرُنَا بِهِ فَيَقُولُ إِنِّي كُنْتُ آمُرُكُمْ بِأَمْرٍ وَأُخَالِفُكُمْ إِلَى غَيْرِهِ ‏","","",""],[20796,20796,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ يَعْنِي الصَّائِغَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20797,20797,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَنَا ‏ ‏يَحْيَى بْنُ قَيْسٍ الْمَازِنِيُّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَطَاءً ‏ ‏عَنْ الدِّينَارِ بِالدِّينَارِ وَبَيْنَهُمَا فَضْلٌ وَالدِّرْهَمِ بِالدِّرْهَمِ قَالَ كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يُحِلُّهُ فَقَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏إِنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُحَدِّثُ بِمَا لَمْ يَسْمَعْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَلَغَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ إِنِّي لَمْ أَسْمَعْهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏حَدَّثَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الرِّبَا إِلَّا فِي ‏ ‏النَّسِيئَةِ ‏ ‏أَوْ ‏ ‏النُّقْرَةِ ‏","","",""],[20798,20798,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏الْكَعْبَةِ ‏","","",""],[20799,20799,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏أَخْبَرَنَا قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏يُحَدِّثُ ‏ ‏سَعْدًا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ ‏ ‏بِالطَّاعُونِ ‏ ‏بِأَرْضٍ فَلَا تَدْخُلُوهَا وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا مِنْهَا قَالَ قُلْتُ أَنْتَ سَمِعْتَهُ يُحَدِّثُ ‏ ‏سَعْدًا ‏ ‏وَهُوَ لَا يُنْكِرُ قَالَ نَعَمْ ‏","","",""],[20800,20800,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُثْمَانَ النَّهْدِيُّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُمَيْمَةَ بِنْتِ زَيْنَبَ ‏ ‏وَنَفْسُهَا ‏ ‏تَقَعْقَعُ ‏ ‏كَأَنَّهَا فِي ‏ ‏شَنٍّ ‏ ‏فَقَالَ ‏ ‏لِلَّهِ مَا أَخَذَ وَلِلَّهِ مَا أَعْطَى وَكُلٌّ إِلَى أَجَلٍ مُسَمًّى قَالَ فَدَمَعَتْ عَيْنَاهُ فَقَالَ لَهُ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَتَبْكِي أَوَلَمْ تَنْهَ عَنْ الْبُكَاءِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هِيَ رَحْمَةٌ جَعَلَهَا اللَّهُ فِي قُلُوبِ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""]];
